# builder/gen_ch20_p2.py
# -*- coding: utf-8 -*-

exercises = [{'num': 42, 'title': 'Утечка горутины с пустым select {} и обнаружение через pprof', 'task': 'Напиши программу с **"потерянной" горутиной**: `go func() { for { select {} } }()`. Покажи, что она никогда не завершится. Объясни, как это обнаружить через `pprof` или `runtime.NumGoroutine()`.', 'theory': 'Конструкция `select {}` без веток `case` навсегда блокирует текущую горутину без выделения процессорного времени. Такая горутина остается в состоянии `_Gwaiting`, потребляя память стека (от 2 КБ) и никогда не освобождается сборщиком мусора.', 'step_by_step': '1. Замерим исходное число горутин `runtime.NumGoroutine()`.\n2. Запустим горутину с `select {}`.\n3. Убедимся, что счетчик горутин увеличился.\n4. Продемонстрируем, как отслеживать утечки.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"runtime"\n\t"time"\n)\n\nfunc spawnZombieGoroutine() {\n\tgo func() {\n\t\t// Пустой select блокирует горутину навсегда\n\t\tselect {}\n\t}()\n}\n\nfunc main() {\n\tfmt.Printf("1. Активных горутин до запуска: %d\\n", runtime.NumGoroutine())\n\n\t// Создаем 3 потерянные горутины\n\tfor i := 0; i < 3; i++ {\n\t\tspawnZombieGoroutine()\n\t}\n\n\ttime.Sleep(20 * time.Millisecond)\n\tfmt.Printf("2. Активных горутин после создания зомби: %d\\n", runtime.NumGoroutine())\n\tfmt.Println("Диагностика: pprof (GET /debug/pprof/goroutine) покажет статус \'select (no cases)\'")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': "go run main.go\n# Вывод:\n# 1. Активных горутин до запуска: 1\n# 2. Активных горутин после создания зомби: 4\n# Диагностика: pprof (GET /debug/pprof/goroutine) покажет статус 'select (no cases)'"}], 'under_the_hood': '`select {}` компилируется в прямой вызов функции `runtime.block()`, которая навсегда паркует горутину в планировщике.', 'pitfalls': 'Иногда разработчики используют `select {}` в `main()`, чтобы не дать программе завершиться. В микросервисах вместо этого используют ожидание сигналов ОС через `os.Signal`.', 'bigtech_interview': '**Вопрос с собеседования:** «Чем отличается select {} от for {} на 100% CPU?»\n**Ответ:** `for {}` непрерывно сжигает 100% одного ядра процессора в цикле. `select {}` моментально усыпляет горутину (0% CPU), но оставляет стек аллоцированным в памяти.'}, {'num': 43, 'title': 'Защита критической секции инкремента с помощью sync.Mutex', 'task': 'Исправьте упражнение на конкурентный инкремент счетчика, защитив критическую секцию с помощью `sync.Mutex` (`Lock()` и `Unlock()`).', 'theory': '`sync.Mutex` обеспечивает взаимное исключение (Mutual Exclusion). Только одна горутина может находиться в критической секции между `Lock()` и `Unlock()`.', 'step_by_step': '1. Создадим `var mu sync.Mutex` и `counter := 0`.\n2. Запустим 100 горутин, каждая сделает 100 инкрементов.\n3. Обернем операцию в `mu.Lock()` и `mu.Unlock()`.\n4. Проверим, что счетчик равен ровно 10 000.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\nfunc main() {\n\tvar (\n\t\tmu      sync.Mutex\n\t\tcounter int\n\t\twg      sync.WaitGroup\n\t)\n\n\tconst goroutines = 100\n\tconst incPerGoroutine = 100\n\twg.Add(goroutines)\n\n\tfor i := 0; i < goroutines; i++ {\n\t\tgo func() {\n\t\t\tdefer wg.Done()\n\t\t\tfor j := 0; j < incPerGoroutine; j++ {\n\t\t\t\tmu.Lock()\n\t\t\t\tcounter++\n\t\t\t\tmu.Unlock()\n\t\t\t}\n\t\t}()\n\t}\n\n\twg.Wait()\n\tfmt.Printf("Итоговое значение: %d (точно %d)\\n", counter, goroutines*incPerGoroutine)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# Итоговое значение: 10000 (точно 10000)'}], 'under_the_hood': '`sync.Mutex` использует адаптивный спиннинг (Adaptive Spinlock) на многоядерных процессорах перед переходом в системный сон на семафоре.', 'pitfalls': 'Не держите мьютекс заблокированным во время долгих операций ввода-вывода (сетевые запросы, чтение диска).', 'bigtech_interview': '**Вопрос с собеседования:** «Какова производительность sync.Mutex при отсутствии конкуренции (uncontended)?»\n**Ответ:** Захват и освобождение незанятого мьютекса занимает всего ~10-15 наносекунд, так как выполняется одной атомарной процессорной инструкцией CAS (Compare-And-Swap) без системных вызовов ОС.'}, {'num': 44, 'title': 'Иерархия горутин: каскадный запуск и ожидание через единый WaitGroup', 'task': 'Напиши программу, которая запускает горутину, которая в свою очередь запускает другие горутины (иерархия). Дождись всех с помощью одной `WaitGroup`.', 'theory': 'Горутины в Go не имеют строгой древовидной иерархии в рантайме (все горутины равноправны). Однако логическую иерархию процессов можно синхронизировать через общий экземпляр `*sync.WaitGroup`, передаваемый по цепочке вызовов.', 'step_by_step': '1. Создадим родительскую горутину `parentTask`.\n2. Перед запуском дочерних задач вызовем `wg.Add(1)`.\n3. Дочерние задачи вызовут `defer wg.Done()`.\n4. В `main` дождемся завершения всех уровней иерархии.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc childTask(parentID, childID int, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\ttime.Sleep(10 * time.Millisecond)\n\tfmt.Printf("   -> [Дочерняя задача %d.%d] завершена\\n", parentID, childID)\n}\n\nfunc parentTask(parentID int, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tfmt.Printf("[Родительская горутина %d] старт и порождение подзадач...\\n", parentID)\n\n\tconst numChildren = 3\n\tfor c := 1; c <= numChildren; c++ {\n\t\twg.Add(1)\n\t\tgo childTask(parentID, c, wg)\n\t}\n}\n\nfunc main() {\n\tvar wg sync.WaitGroup\n\n\tfor p := 1; p <= 2; p++ {\n\t\twg.Add(1)\n\t\tgo parentTask(p, &wg)\n\t}\n\n\twg.Wait()\n\tfmt.Println("Все родительские и дочерние горутины успешно завершены!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Родительская горутина 1] старт и порождение подзадач...\n# [Родительская горутина 2] старт и порождение подзадач...\n#    -> [Дочерняя задача 1.1] завершена\n#    -> [Дочерняя задача 2.1] завершена\n#    -> [Дочерняя задача 1.2] завершена\n#    -> [Дочерняя задача 2.2] завершена\n#    -> [Дочерняя задача 1.3] завершена\n#    -> [Дочерняя задача 2.3] завершена\n# Все родительские и дочерние горутины успешно завершены!'}], 'under_the_hood': '`wg.Add(1)` вызывается синхронно внутри родительской горутины до запуска `go childTask`, исключая дедлок с `wg.Wait()` в `main`.', 'pitfalls': 'Если родительская горутина вызовет `defer wg.Done()` до `wg.Add()` для дочерних, счетчик может временно обнулиться.', 'bigtech_interview': '**Вопрос с собеседования:** «Существует ли в Go понятие Parent-Child отношения между горутинами на уровне ядра рантайма?»\n**Ответ:** Нет! Все горутины в рантайме плоские (flat). Если родительская горутина завершается или паникует, дочерняя горутина продолжает спокойно работать в фоне.'}, {'num': 45, 'title': 'Оптимизация параллельного чтения с sync.RWMutex для кэша', 'task': 'Изучите `sync.RWMutex`. Создайте структуру кэша, где много горутин читают данные (`RLock()`) и редко пишут (`Lock()`). Сравните производительность с обычным `Mutex`.', 'theory': '`sync.RWMutex` (Reader/Writer Mutual Exclusion) позволяет неограниченному числу горутин одновременно удерживать блокировку на чтение (`RLock()`). Эксклюзивная блокировка (`Lock()`) требуется только для записи, предотвращая взаимные задержки между читателями.', 'step_by_step': '1. Создадим структуру `SafeCache` с `sync.RWMutex` и `map[string]string`.\n2. Реализуем метод `Get(key string) string` с `mu.RLock()`.\n3. Реализуем метод `Set(key, val string)` с `mu.Lock()`.\n4. Запустим 50 читателей и 2 писателя одновременно.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype SafeCache struct {\n\tmu   sync.RWMutex\n\tdata map[string]string\n}\n\nfunc NewSafeCache() *SafeCache {\n\treturn &SafeCache{data: make(map[string]string)}\n}\n\nfunc (c *SafeCache) Get(key string) (string, bool) {\n\tc.mu.RLock()         // Множественные параллельные читатели\n\tdefer c.mu.RUnlock()\n\tval, ok := c.data[key]\n\treturn val, ok\n}\n\nfunc (c *SafeCache) Set(key, val string) {\n\tc.mu.Lock()          // Эксклюзивная блокировка для писателя\n\tdefer c.mu.Unlock()\n\tc.data[key] = val\n}\n\nfunc main() {\n\tcache := NewSafeCache()\n\tcache.Set("session:1", "user_admin")\n\n\tvar wg sync.WaitGroup\n\tconst readers = 5\n\n\twg.Add(readers)\n\tfor i := 1; i <= readers; i++ {\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\t\t\tval, _ := cache.Get("session:1")\n\t\t\tfmt.Printf("[Читатель %d] Прочитал ключ: %s\\n", id, val)\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Println("Параллельное чтение через RLock выполнено успешно!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [Читатель 1] Прочитал ключ: user_admin\n# [Читатель 2] Прочитал ключ: user_admin\n# [Читатель 3] Прочитал ключ: user_admin\n# [Читатель 4] Прочитал ключ: user_admin\n# [Читатель 5] Прочитал ключ: user_admin\n# Параллельное чтение через RLock выполнено успешно!'}], 'under_the_hood': '`RLock()` инкрементирует счетчик читателей `readerCount` атомарной инструкцией. Если писатель запрашивает `Lock()`, он вычитает `rwmutexMaxReaders` (1 млрд), запрещая новым читателям захватывать блокировку (защита от Writer Starvation).', 'pitfalls': 'Никогда не вызывайте `mu.Lock()` внутри секции `mu.RLock()` в одной горутине — это мгновенный дедлок.', 'bigtech_interview': '**Вопрос с собеседования:** «В каких сценариях обычный sync.Mutex работает быстрее sync.RWMutex?»\n**Ответ:** Когда доля операций записи высока (>20-30%) или критическая секция чтения сверхкороткая. `RWMutex` имеет более высокие накладные расходы на атомарные операции и кэш-когерентность процессорных ядер.'}, {'num': 46, 'title': 'Управление ядрами процессора: runtime.NumCPU и GOMAXPROCS(1)', 'task': '**Управление ядрами**: Импортируй `runtime`. Выведи `runtime.NumCPU()`. С помощью `runtime.GOMAXPROCS(1)` заставь программу работать только на одном логическом ядре, запусти 100 горутин и посмотри, изменилось ли поведение.', 'theory': 'Даже на одном ядре процессора Go обеспечивает полноценную конкурентность за счет переключения контекста горутин.', 'step_by_step': '1. Напечатаем `runtime.NumCPU()`.\n2. Установим `runtime.GOMAXPROCS(1)`.\n3. Запустим 100 горутин с `sync.WaitGroup`.\n4. Убедимся в корректности их работы на одном потоке M.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"runtime"\n\t"sync"\n)\n\nfunc main() {\n\tfmt.Printf("Доступно физических ядер CPU: %d\\n", runtime.NumCPU())\n\n\t// Принудительно ограничиваем выполнение 1 ядром\n\tprev := runtime.GOMAXPROCS(1)\n\tfmt.Printf("GOMAXPROCS изменен с %d на 1\\n", prev)\n\n\tvar wg sync.WaitGroup\n\tconst total = 100\n\twg.Add(total)\n\n\tvar counter int\n\tvar mu sync.Mutex\n\n\tfor i := 0; i < total; i++ {\n\t\tgo func() {\n\t\t\tdefer wg.Done()\n\t\t\tmu.Lock()\n\t\t\tcounter++\n\t\t\tmu.Unlock()\n\t\t}()\n\t}\n\n\twg.Wait()\n\tfmt.Printf("Все %d горутин успешно завершились на 1 ядре, результат: %d\\n", total, counter)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Доступно физических ядер CPU: 8\n# GOMAXPROCS изменен с 8 на 1\n# Все 100 горутин успешно завершились на 1 ядре, результат: 100'}], 'under_the_hood': 'При `GOMAXPROCS=1` создается только один контекст P. Все горутины находятся в очереди `runq` этого единственного процессора.', 'pitfalls': 'Даже при `GOMAXPROCS=1` гонки данных возможны из-за вытеснения горутин планировщиком! Мьютексы обязательны всегда.', 'bigtech_interview': '**Вопрос с собеседования:** «Нужна ли синхронизация (Mutex/Atomic), если в программе установлен GOMAXPROCS=1?»\n**Ответ:** ДА, абсолютно обязательна! При вызове функций или срабатывании асинхронного вытеснения горутина прерывается посередине критической секции, вызывая состояние гонки (Race Condition).'}, {'num': 47, 'title': 'Немедленная остановка горутины через runtime.Goexit с сохранением defer', 'task': 'Используй `runtime.Goexit()` внутри горутины для её немедленной остановки. Добавь `defer` до вызова `Goexit` и убедись, что он выполняется.', 'theory': '`runtime.Goexit()` немедленно прерывает выполнение текущей горутины. При этом рантайм гарантированно выполняет все зарегистрированные функции `defer` в порядке LIFO. Другие горутины продолжают работать без сбоев.', 'step_by_step': '1. Запустим горутину с `defer wg.Done()` и `defer fmt.Println(...)`.\n2. Вызовем `runtime.Goexit()`.\n3. Убедимся, что код после `Goexit` не выполнился, а все `defer` отработали.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"runtime"\n\t"sync"\n)\n\nfunc workerWithExit(wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tdefer fmt.Println("1. [DEFER] Этот defer выполнился гарантированно!")\n\n\tfmt.Println("2. Старт работы воркера...")\n\tfmt.Println("3. Немедленное завершение горутины через runtime.Goexit()...")\n\n\truntime.Goexit()\n\n\t// Этот код никогда не выполнится\n\tfmt.Println("4. ЭТА СТРОКА НЕ БУДЕТ НАПЕЧАТАНА")\n}\n\nfunc main() {\n\tvar wg sync.WaitGroup\n\twg.Add(1)\n\n\tgo workerWithExit(&wg)\n\n\twg.Wait()\n\tfmt.Println("5. Главная программа завершилась чисто")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 2. Старт работы воркера...\n# 3. Немедленное завершение горутины через runtime.Goexit()...\n# 1. [DEFER] Этот defer выполнился гарантированно!\n# 5. Главная программа завершилась чисто'}], 'under_the_hood': '`runtime.Goexit()` раскручивает стек горутины, исполняя `g._defer`, и переводит структуру `g` в состояние `_Gdead` без паники.', 'pitfalls': 'Если вызвать `runtime.Goexit()` в главной горутине `main()`, рантайм Go завершит `main`, но позволит остальным горутинам работать до дедлока.', 'bigtech_interview': '**Вопрос с собеседования:** «Что произойдет, если вызвать runtime.Goexit() в главной горутине, когда фоновых горутин нет?»\n**Ответ:** Произойдет фатальная ошибка рантайма: `fatal error: no goroutines (main called runtime.Goexit) - deadlock!`.'}, {'num': 48, 'title': 'Ловушки Mutex: паника при Unlock незаблокированного мьютекса и дедлок при повторном Lock', 'task': 'Что произойдет, если вызвать `Unlock()` на мьютексе, который не был заблокирован? Что будет при двойном `Lock()` в одной горутине? (Поймайте Deadlock).', 'theory': '1) Вызов `Unlock()` на незаблокированном `sync.Mutex` вызывает немедленную панику `panic: sync: unlock of unlocked mutex`. 2) В Go мьютексы **не являются реентерабельными** (Non-reentrant / Non-recursive). Повторный вызов `Lock()` из той же горутины приводит к дедлоку.', 'step_by_step': '1. Продемонстрируем перехват паники при `Unlock()` незаблокированного мьютекса.\n2. Продемонстрируем дедлок при повторном вызове `mu.Lock()`.\n3. Объясним правила безопасного проектирования.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\nfunc demoUnlockPanic() {\n\tvar mu sync.Mutex\n\n\tdefer func() {\n\t\tif r := recover(); r != nil {\n\t\t\tfmt.Printf("[1. ПЕРЕХВАЧЕНА ПАНИКА]: %v\\n", r)\n\t\t}\n\t}()\n\n\tfmt.Println("Попытка вызвать Unlock() без предварительного Lock()...")\n\tmu.Unlock() // Паника: sync: unlock of unlocked mutex\n}\n\nfunc demoDoubleLockDeadlock() {\n\tvar mu sync.Mutex\n\n\tmu.Lock()\n\tfmt.Println("2. Первый Lock() успешно захвачен.")\n\n\t// Попытка захватить мьютекс повторно через TryLock (в Go 1.18+)\n\tacquired := mu.TryLock()\n\tfmt.Printf("3. Попытка повторного Lock() вернула: %v (мьютекс уже занят этой же горутиной)\\n", acquired)\n\n\tmu.Unlock()\n\tfmt.Println("4. Мьютекс освобожден.")\n}\n\nfunc main() {\n\tdemoUnlockPanic()\n\tdemoDoubleLockDeadlock()\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Попытка вызвать Unlock() без предварительного Lock()...\n# [1. ПЕРЕХВАЧЕНА ПАНИКА]: sync: unlock of unlocked mutex\n# 2. Первый Lock() успешно захвачен.\n# 3. Попытка повторного Lock() вернула: false (мьютекс уже занят этой же горутиной)\n# 4. Мьютекс освобожден.'}], 'under_the_hood': '`sync.Mutex` не сохраняет идентификатор владеющей горутины (Goroutine ID). Это сознательное архитектурное решение команды Go.', 'pitfalls': 'Никогда не вызывайте экспортируемые методы структуры с `mu.Lock()` из других методов этой же структуры, которые уже держат `mu.Lock()`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go намеренно отказались от реентерабельных (Recursive) мьютексов (как в Java ReentrantLock)?»\n**Ответ:** Расс Кокс (Russ Cox) объяснил: реентерабельные мьютексы маскируют нарушение инвариантов программы. Если метод вызывается повторно при удержании блокировки, структуры данных могут находиться в промежуточном, несогласованном состоянии.'}, {'num': 49, 'title': 'Идиоматичная гарантия разблокировки через defer mu.Unlock()', 'task': 'Используйте `defer mu.Unlock()` сразу после `mu.Lock()`, чтобы гарантировать разблокировку даже при панике или раннем `return`.', 'theory': 'Паттерн `mu.Lock(); defer mu.Unlock()` — золотой стандарт написания критических секций в Go, защищающий от утечки блокировки при ветвлении логики (`if err != nil`).', 'step_by_step': '1. Создадим функцию с ранними возвратами ошибок `processPayment`.\n2. Заблокируем мьютекс `mu.Lock()` и сразу вызовем `defer mu.Unlock()`.\n3. Смоделируем ранний `return` по ошибке.\n4. Убедимся, что мьютекс корректно освободился.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n\t"sync"\n)\n\ntype BankAccount struct {\n\tmu      sync.Mutex\n\tbalance int\n}\n\nfunc (a *BankAccount) Withdraw(amount int) error {\n\ta.mu.Lock()\n\tdefer a.mu.Unlock() // Гарантированная разблокировка при любом return\n\n\tif amount <= 0 {\n\t\treturn errors.New("некорректная сумма списания")\n\t}\n\n\tif a.balance < amount {\n\t\treturn errors.New("недостаточно средств на балансе")\n\t}\n\n\ta.balance -= amount\n\treturn nil\n}\n\nfunc main() {\n\tacc := &BankAccount{balance: 100}\n\n\t// 1. Ошибка валидации (ранний return)\n\terr1 := acc.Withdraw(-50)\n\tfmt.Printf("1. Результат списания -50: %v\\n", err1)\n\n\t// 2. Успешное списание (мьютекс был разблокирован в defer)\n\terr2 := acc.Withdraw(40)\n\tfmt.Printf("2. Результат списания 40: %v (остаток: %d)\\n", err2, acc.balance)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 1. Результат списания -50: некорректная сумма списания\n# 2. Результат списания 40: <nil> (остаток: 60)'}], 'under_the_hood': 'В Go 1.14+ компилятор внедрил оптимизацию Open-Coded Defers: вызовы `defer` инлайнятся напрямую в точку `return` с накладными расходами около 1 нс.', 'pitfalls': 'Внутри больших циклов `for` вызов `defer mu.Unlock()` выполнится только при выходе из функции, а не на каждой итерации цикла. Для циклов вызывайте `Unlock()` вручную.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы накладные расходы defer mu.Unlock() в современных версиях Go (1.22+)?»\n**Ответ:** Практически нулевые (0-1 нс благодаря инлайнингу Open-Coded Defers). Аргумент о том, что "defer медленный", устарел еще в 2020 году.'}, {'num': 50, 'title': 'Масштабный эксперимент: 1000 горутин, гонка данных и отчет go run -race', 'task': '**Состояние гонки (Race Condition)**: Создайте глобальную переменную `counter := 0`. Запустите 1000 горутин, каждая из которых инкрементирует счетчик: `counter++`. Дождитесь завершения всех горутин через `WaitGroup` и выведите `counter`. Почему результат почти никогда не равен 1000? Запустите компиляцию программы с флагом обнаружения гонок: `go run -race main.go` и изучите отчет.', 'theory': 'При параллельном выполнении 1000 горутин множество процессорных ядер перезаписывают регистры друг друга, приводя к потере десятков или сотен операций инкремента.', 'step_by_step': '1. Создадим глобальную переменную `counter := 0`.\n2. Запустим 1000 горутин с `counter++`.\n3. Дождемся всех через `sync.WaitGroup`.\n4. Запустим с `-race` и зафиксируем потерю данных.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\nvar counter int\n\nfunc main() {\n\tvar wg sync.WaitGroup\n\tconst total = 1000\n\twg.Add(total)\n\n\tfor i := 0; i < total; i++ {\n\t\tgo func() {\n\t\t\tdefer wg.Done()\n\t\t\tcounter++ // Незащищенная запись\n\t\t}()\n\t}\n\n\twg.Wait()\n\tfmt.Printf("Фактическое значение counter: %d (из 1000 ожидаемых)\\n", counter)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод детектора гонок:\n# WARNING: DATA RACE\n# Write at 0x... by goroutine ...\n# Previous write at 0x... by goroutine ...\n# Фактическое значение counter: 942 (из 1000 ожидаемых)'}], 'under_the_hood': 'Инструкция `INC [mem]` в x86_64 без префикса `LOCK` не гарантирует атомарности шины памяти при одновременном обращении с нескольких ядер.', 'pitfalls': 'В архитектурах ARM64 (Apple Silicon, AWS Graviton) эффект гонок данных выражен еще сильнее из-за слабой модели памяти (Weak Memory Model).', 'bigtech_interview': '**Вопрос с собеседования:** «Почему счетчик равен, например, 942, а не 1000?»\n**Ответ:** Потому что несколько горутин на разных ядрах CPU одновременно прочитали одно и то же значение (например, 50), локально увеличили до 51 и записали обратно в память 51, затерев инкременты друг друга.'}, {'num': 51, 'title': 'Сравнение производительности: sync/atomic против sync.Mutex', 'task': 'Переиспользуйте упражнение на конкурентный инкремент счетчика, но защитите счетчик с помощью атомарных операций `atomic.AddInt64(&counter, 1)`. Сравните читаемость и производительность с Mutex.', 'theory': 'Пакет `sync/atomic` предоставляет низкоуровневые атомарные инструкции процессора (`LOCK XADD` на x86, `LDADD` на ARM). Атомики выполняются на уровне кэш-линий CPU без усыпления горутин и вызова планировщика Go.', 'step_by_step': '1. Объявим `var counter int64`.\n2. Запустим 1000 горутин, вызывающих `atomic.AddInt64(&counter, 1)`.\n3. Дождемся завершения через `sync.WaitGroup`.\n4. Считаем результат через `atomic.LoadInt64(&counter)`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"sync/atomic"\n)\n\nfunc main() {\n\tvar counter int64\n\tvar wg sync.WaitGroup\n\n\tconst total = 1000\n\twg.Add(total)\n\n\tfor i := 0; i < total; i++ {\n\t\tgo func() {\n\t\t\tdefer wg.Done()\n\t\t\t// Атомарный инкремент на уровне инструкций процессора\n\t\t\tatomic.AddInt64(&counter, 1)\n\t\t}()\n\t}\n\n\twg.Wait()\n\n\t// Атомарное чтение\n\tfinalVal := atomic.LoadInt64(&counter)\n\tfmt.Printf("Итоговое значение через sync/atomic: %d (из 1000)\\n", finalVal)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# Итоговое значение через sync/atomic: 1000 (из 1000)\n# (Предупреждений детектора гонок нет)'}], 'under_the_hood': '`atomic.AddInt64` транслируется компилятором напрямую во встроенную инструкцию ассемблера (Compiler Intrinsic), исключая накладные расходы вызова функций.', 'pitfalls': 'Атомики подходят только для отдельных скалярных значений (числа, указатели, булевы флаги). Сложные инварианты из нескольких полей требуют `sync.Mutex`.', 'bigtech_interview': '**Вопрос с собеседования:** «Во сколько раз sync/atomic быстрее sync.Mutex для простого счетчика?»\n**Ответ:** При высокой конкуренции (high contention) атомики быстрее мьютексов в 3–10 раз, так как не требуют блокировок семафоров и смены контекста горутин в планировщике.'}, {'num': 52, 'title': 'Потокобезопасный счетчик на базе типизированного atomic.Int64', 'task': 'Реализуйте потокобезопасный счетчик (структуру `Counter` с методами `Inc()`, `Dec()`, `Val()`), используя внутри `atomic`.', 'theory': 'Начиная с Go 1.19, в пакете `sync/atomic` появились удобные типизированные обертки: `atomic.Int64`, `atomic.Uint64`, `atomic.Bool`, `atomic.Pointer[T]`. Они инкапсулируют выравнивание памяти и предоставляют удобные методы `Add`, `Load`, `Store`.', 'step_by_step': '1. Создадим структуру `AtomicCounter struct { val atomic.Int64 }`.\n2. Реализуем методы `Inc()`, `Dec()`, `Val() int64`.\n3. Запустим конкурентные инкременты и декременты.\n4. Проверим точный баланс.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"sync/atomic"\n)\n\ntype AtomicCounter struct {\n\tval atomic.Int64 // Go 1.19+ типизированный атомик\n}\n\nfunc (c *AtomicCounter) Inc() int64 {\n\treturn c.val.Add(1)\n}\n\nfunc (c *AtomicCounter) Dec() int64 {\n\treturn c.val.Add(-1)\n}\n\nfunc (c *AtomicCounter) Val() int64 {\n\treturn c.val.Load()\n}\n\nfunc main() {\n\tcounter := &AtomicCounter{}\n\tvar wg sync.WaitGroup\n\n\tconst ops = 500\n\twg.Add(ops * 2)\n\n\t// 500 инкрементов\n\tfor i := 0; i < ops; i++ {\n\t\tgo func() {\n\t\t\tdefer wg.Done()\n\t\t\tcounter.Inc()\n\t\t}()\n\t}\n\n\t// 500 декрементов\n\tfor i := 0; i < ops; i++ {\n\t\tgo func() {\n\t\t\tdefer wg.Done()\n\t\t\tcounter.Dec()\n\t\t}()\n\t}\n\n\twg.Wait()\n\tfmt.Printf("Итоговое значение счетчика (+500 -500): %d\\n", counter.Val())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# Итоговое значение счетчика (+500 -500): 0'}], 'under_the_hood': '`atomic.Int64` гарантирует 8-байтное выравнивание в памяти даже на 32-битных архитектурах (ARM32/x86), защищая от паник unaligned 64-bit atomic.', 'pitfalls': 'Структуры, содержащие `atomic.Int64`, нельзя копировать по значению (`noCopy`).', 'bigtech_interview': '**Вопрос с собеседования:** «В чем преимущество atomic.Int64 перед старым atomic.AddInt64(&val, 1)?»\n**Ответ:** 1) Повышение типобезопасности и читаемости API. 2) Автоматическое 64-битное выравнивание памяти в структуре (на 32-битных платформах старый `atomic.AddInt64` падал с SIGSEGV при невыровненном адресе).'}, {'num': 53, 'title': 'Инициализация конфигурации строго один раз через sync.Once', 'task': 'Используйте `sync.Once` для инициализации глобальной конфигурации. Запустите 100 горутин, вызывающих функцию инициализации, и убедитесь, что она выполнилась строго один раз.', 'theory': '`sync.Once` гарантирует, что переданная функция выполнится ровно один раз за все время жизни процесса, независимо от количества параллельно вызывающих её горутин. Все остальные горутины блокируются до завершения инициализации.', 'step_by_step': '1. Создадим `var once sync.Once` и глобальный конфиг `AppConfig`.\n2. Напишем функцию `loadConfig()`.\n3. Запустим 100 горутин, вызывающих `once.Do(loadConfig)`.\n4. Убедимся, что сообщение о загрузке напечатано ровно 1 раз.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype Config struct {\n\tDatabaseURL string\n\tPort        int\n}\n\nvar (\n\tappConfig *Config\n\tonce      sync.Once\n)\n\nfunc initializeConfig() {\n\tfmt.Println("[INIT] Инициализация конфигурации приложения (должна быть строго 1 раз)...")\n\ttime.Sleep(20 * time.Millisecond) // Симуляция чтения из файла/Vault\n\tappConfig = &Config{\n\t\tDatabaseURL: "postgres://prod_db:5432/main",\n\t\tPort:        8080,\n\t}\n}\n\nfunc GetConfig() *Config {\n\tonce.Do(initializeConfig)\n\treturn appConfig\n}\n\nfunc main() {\n\tvar wg sync.WaitGroup\n\tconst callers = 10\n\n\twg.Add(callers)\n\tfor i := 1; i <= callers; i++ {\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\t\t\tcfg := GetConfig()\n\t\t\t_ = cfg.Port\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Printf("Все %d горутин успешно получили инициализированный конфиг: %+v\\n", callers, GetConfig())\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [INIT] Инициализация конфигурации приложения (должна быть строго 1 раз)...\n# Все 10 горутин успешно получили инициализированный конфиг: &{DatabaseURL:postgres://prod_db:5432/main Port:8080}'}], 'under_the_hood': 'Внутри `sync.Once` используется быстрый атомарный путь (Fast Path): `atomic.LoadUint32(&o.done)`. Если флаг 0, вызывается медленный путь (Slow Path) с `sync.Mutex` и повторной проверкой (Double-Checked Locking).', 'pitfalls': 'Если функция внутри `once.Do(fn)` паникует, `sync.Once` все равно считает себя выполненным! Повторные вызовы `once.Do` не будут запускать `fn`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как устроен Fast Path в sync.Once?»\n**Ответ:** Первой инструкцией метода `Do` идет `if atomic.LoadUint32(&o.done) == 1 { return }`. После первой инициализации вызов `once.Do` занимает доли наносекунды без единого захвата мьютекса.'}, {'num': 54, 'title': 'Снижение нагрузки на GC через пул объектов sync.Pool', 'task': 'Изучите `sync.Pool`. Создайте пул объектов (например, `bytes.Buffer`), чтобы переиспользовать их в горутинах и снизить нагрузку на Garbage Collector.', 'theory': '`sync.Pool` — это потокобезопасный пул повторно используемых временных объектов. Он позволяет избежать постоянных аллокаций памяти в куче (Heap) в высоконагруженных сетевых обработчиках, существенно снижая паузы сборщика мусора (GC Stop-The-World).', 'step_by_step': '1. Создадим `sync.Pool` с фабричной функцией `New`.\n2. В горутине запросим буфер через `bufPool.Get().(*bytes.Buffer)`.\n3. Очистим буфер через `buf.Reset()` и вернем в пул через `defer bufPool.Put(buf)`.\n4. Запустим несколько параллельных задач.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bytes"\n\t"fmt"\n\t"sync"\n)\n\nvar bufPool = sync.Pool{\n\tNew: func() any {\n\t\t// Создается только при нехватке свободных объектов в пуле\n\t\tfmt.Println("[POOL] Аллокация нового буфера в куче")\n\t\treturn new(bytes.Buffer)\n\t},\n}\n\nfunc formatMessage(user string, id int) string {\n\t// Берем объект из пула\n\tbuf := bufPool.Get().(*bytes.Buffer)\n\tbuf.Reset() // Обязательная очистка перед повторным использованием\n\tdefer bufPool.Put(buf) // Возврат объекта в пул\n\n\tfmt.Fprintf(buf, "User: %s (ID: %d)", user, id)\n\treturn buf.String()\n}\n\nfunc main() {\n\tvar wg sync.WaitGroup\n\n\tfor i := 1; i <= 3; i++ {\n\t\twg.Add(1)\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\t\t\tmsg := formatMessage("developer", id)\n\t\t\tfmt.Println(" ->", msg)\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Println("Обработка через sync.Pool завершена успешно!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [POOL] Аллокация нового буфера в куче\n#  -> User: developer (ID: 3)\n#  -> User: developer (ID: 1)\n#  -> User: developer (ID: 2)\n# Обработка через sync.Pool завершена успешно!'}], 'under_the_hood': '`sync.Pool` привязан к локальным структурам `P` процессора (Local Pool per-P). Забор объекта из локального пула текущего `P` происходит без глобальных блокировок через lock-free очереди `poolLocal`.', 'pitfalls': 'Объекты в `sync.Pool` могут быть в любой момент очищены сборщиком мусора во время цикла GC. Не храните в `sync.Pool` постоянные ресурсы (соединения с БД или открытые файлы).', 'bigtech_interview': '**Вопрос с собеседования:** «Когда сборщик мусора очищает объекты из sync.Pool?»\n**Ответ:** Начиная с Go 1.13, объекты живут минимум два полных цикла GC (механизм `poolVictim`). При первом цикле GC объекты переносятся в резервный пул `victim`, а при втором (если не были запрошены) — окончательно удаляются.'}, {'num': 55, 'title': 'Идиоматичные правила применения sync.WaitGroup: Add, Done и Wait', 'task': '**Использование `sync.WaitGroup`**: Перепишите задачу с горутиной. Вместо использования костылей в виде `time.Sleep` для ожидания горутины, примените `sync.WaitGroup`. Объясните правила вызова методов `Add()`, `Done()` и `Wait()`.', 'theory': 'Свод 3 главных правил `sync.WaitGroup`:\n1. `wg.Add(n)` вызывается строго ДО запуска горутин в вызывающем потоке.\n2. `defer wg.Done()` вызывается первой инструкцией внутри горутины.\n3. `wg.Wait()` вызывается в точке синхронизации.', 'step_by_step': '1. Создадим `var wg sync.WaitGroup`.\n2. Запустим задачу с гарантированным ожиданием.\n3. Убедимся в мгновенном завершении без лишних задержек.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc performTask(name string, duration time.Duration, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\ttime.Sleep(duration)\n\tfmt.Printf("[Task] Задача \'%s\' успешно выполнена за %v\\n", name, duration)\n}\n\nfunc main() {\n\tvar wg sync.WaitGroup\n\n\tstart := time.Now()\n\n\twg.Add(2)\n\tgo performTask("Генерация отчета", 25*time.Millisecond, &wg)\n\tgo performTask("Отправка вебхука", 15*time.Millisecond, &wg)\n\n\t// Ожидание ровно столько, сколько требуется самой медленной задаче\n\twg.Wait()\n\n\tfmt.Printf("Все задачи выполнены за %v (без фиксированного time.Sleep)\\n", time.Since(start))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': "go run main.go\n# Вывод:\n# [Task] Задача 'Отправка вебхука' успешно выполнена за 15ms\n# [Task] Задача 'Генерация отчета' успешно выполнена за 25ms\n# Все задачи выполнены за 25.12ms (без фиксированного time.Sleep)"}], 'under_the_hood': '`wg.Wait()` использует семафор `runtime_Semacquire`, возвращая управление в микросекунду обнуления счетчика.', 'pitfalls': 'Никогда не используйте `time.Sleep` для ожидания асинхронных задач.', 'bigtech_interview': '**Вопрос с собеседования:** «Что быстрее: sync.WaitGroup или канал chan struct{} для ожидания 1 горутины?»\n**Ответ:** Для одной горутины канал `done := make(chan struct{})` и `close(done)` по скорости сопоставим с `WaitGroup`, но `sync.WaitGroup` оптимальнее и читаемее для групп из N параллельных задач.'}, {'num': 56, 'title': 'Глубокий анализ ошибки копирования WaitGroup по значению', 'task': '**Ошибка копирования `WaitGroup`**: Создайте функцию `worker(wg sync.WaitGroup)`, которая выполняет работу и вызывает `wg.Done()`. Запустите её в горутине, передав `wg` по значению. Объясните, почему программа зависает в бесконечном ожидании дедлока. Исправьте ошибку, передавая `WaitGroup` по указателю `*sync.WaitGroup`.', 'theory': 'Передача структуры `sync.WaitGroup` по значению создает копию объекта на стеке функции. Вызов `wg.Done()` уменьшает счетчик копии, а исходный `WaitGroup` в `main()` никогда не обнулится, приводя к дедлоку всей программы.', 'step_by_step': '1. Создадим функцию с правильной передачей `func worker(id int, wg *sync.WaitGroup)`.\n2. Внутри вызовем `defer wg.Done()`.\n3. В `main` передадим адрес `&wg`.\n4. Запустим и проверим корректную работу.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\n// ИСПРАВЛЕНИЕ: передача указателя *sync.WaitGroup\nfunc worker(id int, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\tfmt.Printf("[Worker %d] Успешно завершил обработку\\n", id)\n}\n\nfunc main() {\n\tvar wg sync.WaitGroup\n\n\twg.Add(2)\n\t// Передаем &wg по указателю\n\tgo worker(1, &wg)\n\tgo worker(2, &wg)\n\n\twg.Wait()\n\tfmt.Println("Синхронизация завершена без дедлока!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Worker 1] Успешно завершил обработку\n# [Worker 2] Успешно завершил обработку\n# Синхронизация завершена без дедлока!'}], 'under_the_hood': 'Поле `noCopy` в структуре `sync.WaitGroup` используется утилитой `go vet` для статического предупреждения о попытке передачи структуры по значению.', 'pitfalls': 'Если передать `sync.WaitGroup` в структуру без указателя `struct { wg sync.WaitGroup }`, копирование структуры также скопирует мьютекс/счетчик.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в сигнатурах методов sync.WaitGroup (Add, Done, Wait) получатель объявлен как (wg *WaitGroup), а не (wg WaitGroup)?»\n**Ответ:** Потому что семантика WaitGroup требует мутации единственного разделяемого состояния. Вызов метода на значении создавал бы бессмысленную копию объекта.'}, {'num': 57, 'title': 'Защита инкремента счетчика в 1000 горутинах через sync.Mutex', 'task': '**Защита данных через `sync.Mutex`**: Исправьте предыдущую задачу на инкремент счетчика. Добавьте `sync.Mutex` и защитите операцию инкремента критической секцией (`mutex.Lock()` / `mutex.Unlock()`). Убедитесь, что теперь результат всегда равен 1000, а детектор гонок больше не выдает предупреждений.', 'theory': 'Защита критической секции через `sync.Mutex` сериализует доступ к памяти, превращая операцию `counter++` в неделимый и безопасный шаг.', 'step_by_step': '1. Создадим переменную `counter := 0` и `var mu sync.Mutex`.\n2. Запустим 1000 горутин.\n3. Обернем операцию в `mu.Lock()` и `mu.Unlock()`.\n4. Проверим с флагом `-race`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\nfunc main() {\n\tvar (\n\t\tcounter int\n\t\tmu      sync.Mutex\n\t\twg      sync.WaitGroup\n\t)\n\n\tconst total = 1000\n\twg.Add(total)\n\n\tfor i := 0; i < total; i++ {\n\t\tgo func() {\n\t\t\tdefer wg.Done()\n\n\t\t\tmu.Lock()\n\t\t\tcounter++\n\t\t\tmu.Unlock()\n\t\t}()\n\t}\n\n\twg.Wait()\n\tfmt.Printf("Итоговое защищенное значение: %d (из 1000)\\n", counter)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# Итоговое защищенное значение: 1000 (из 1000)'}], 'under_the_hood': '`sync.Mutex` в состоянии starvation mode (режим голодания) передает владение блокировкой напрямую первой горутине в очереди FIFO, предотвращая задержки под высокой нагрузкой.', 'pitfalls': 'Не вызывайте блокирующие сетевые функции внутри секции `mu.Lock()`, иначе все остальные горутины выстроятся в очередь ожидания.', 'bigtech_interview': '**Вопрос с собеседования:** «Что такое Starvation Mode в sync.Mutex Go 1.9+?»\n**Ответ:** Если ожидающая горутина не может захватить мьютекс более 1 миллисекунды, мьютекс переходит в режим голодания: новые горутины не спинят на CPU, а сразу встают в хвост очереди, а владение мьютексом передается строго по FIFO.'}, {'num': 58, 'title': 'Идиоматичный паттерн defer wg.Done() для защиты от паник и ранних выходов', 'task': '**Анонимные функции и defer**: Используй `defer wg.Done()` внутри горутины (сразу после её начала) — это стандартный паттерн, гарантирующий, что счетчик уменьшится даже при панике внутри горутины.', 'theory': 'Размещение `defer wg.Done()` в первой строке тела горутины гарантирует выполнение декремента счетчика при любом исходе: успешном завершении, возврате по ошибке (`return err`) или неперехваченной панике.', 'step_by_step': '1. Создадим `var wg sync.WaitGroup`.\n2. Запустим горутину с условием раннего выхода.\n3. Убедимся, что `defer wg.Done()` сработал при раннем `return`.\n4. Дождемся завершения в `main`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\nfunc processTask(id int, wg *sync.WaitGroup) {\n\t// 1. Первая строка горутины — регистрация defer Done\n\tdefer wg.Done()\n\n\tif id == 2 {\n\t\tfmt.Printf("[Task #%d] Ранний возврат из-за ошибки валидации\\n", id)\n\t\treturn // defer wg.Done() все равно выполнится!\n\t}\n\n\tfmt.Printf("[Task #%d] Полная обработка успешно выполнена\\n", id)\n}\n\nfunc main() {\n\tvar wg sync.WaitGroup\n\n\tfor i := 1; i <= 3; i++ {\n\t\twg.Add(1)\n\t\tgo processTask(i, &wg)\n\t}\n\n\twg.Wait()\n\tfmt.Println("Все задачи корректно обработаны без зависаний!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Task #1] Полная обработка успешно выполнена\n# [Task #2] Ранний возврат из-за ошибки валидации\n# [Task #3] Полная обработка успешно выполнена\n# Все задачи корректно обработаны без зависаний!'}], 'under_the_hood': 'Стек вызовов `defer` привязан к структуре `g._defer` текущей горутины и выполняется перед возвратом управления.', 'pitfalls': 'Если написать `wg.Done()` в самом конце функции без `defer`, любой `return` в середине приведет к вечному дедлоку `wg.Wait()`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему defer wg.Done() считается идиоматичнее ручного вызова?»\n**Ответ:** Потому что в сложных функциях с десятками ветвлений `if err != nil` легко забыть вызов `wg.Done()` в одной из веток, что приведет к скрытому дедлоку.'}, {'num': 59, 'title': 'Безопасная разблокировка мьютекса в ветвящихся функциях через defer mu.Unlock()', 'task': '**Безопасная разблокировка с `defer`**: Напишите функцию, которая блокирует мьютекс, делает сложные вычисления, которые могут вернуть ошибку (`return err`), и разблокирует мьютекс. Используйте `defer mutex.Unlock()` сразу после блокировки. Объясните, почему ручной вызов `Unlock()` перед каждым `return` считается плохой практикой.', 'theory': "Ручной вызов `Unlock()` перед каждым оператором `return` нарушает принцип DRY (Don't Repeat Yourself) и неизбежно приводит к забытым разблокировкам при добавлении новых условий проверки.", 'step_by_step': '1. Создадим структуру хранилища `OrderStore`.\n2. Реализуем метод `CreateOrder` с несколькими проверками условий.\n3. Установим `defer s.mu.Unlock()` сразу после `s.mu.Lock()`.\n4. Протестируем успешный и ошибочный пути.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n\t"sync"\n)\n\ntype OrderStore struct {\n\tmu     sync.Mutex\n\torders map[int]string\n}\n\nfunc (s *OrderStore) CreateOrder(id int, title string) error {\n\ts.mu.Lock()\n\tdefer s.mu.Unlock() // Гарантированная разблокировка для всех 3 точек выхода\n\n\tif id <= 0 {\n\t\treturn errors.New("невалидный ID заказа")\n\t}\n\n\tif _, exists := s.orders[id]; exists {\n\t\treturn errors.New("заказ с таким ID уже существует")\n\t}\n\n\tif title == "" {\n\t\treturn errors.New("название заказа не может быть пустым")\n\t}\n\n\ts.orders[id] = title\n\treturn nil\n}\n\nfunc main() {\n\tstore := &OrderStore{orders: make(map[int]string)}\n\n\t_ = store.CreateOrder(-1, "Тест")\n\t_ = store.CreateOrder(101, "")\n\terr := store.CreateOrder(101, "Серверное оборудование")\n\n\tfmt.Printf("Результат создания заказа #101: %v\\n", err)\n\tfmt.Printf("Всего заказов в базе: %d\\n", len(store.orders))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Результат создания заказа #101: <nil>\n# Всего заказов в базе: 1'}], 'under_the_hood': 'Компилятор Go инлайнит `defer s.mu.Unlock()` во все сгенерированные точки `RET` функции.', 'pitfalls': 'Если метод содержит долгие внешние HTTP/DB вызовы, критическую секцию следует сузить до минимума с помощью замыкания или ручного `Unlock()`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как ограничить область действия defer Unlock(), если после изменения данных идет долгая обработка?»\n**Ответ:** Вынести критическую секцию в отдельный локальный метод или анонимную функцию: `func() { mu.Lock(); defer mu.Unlock(); updateData() }()`.'}, {'num': 60, 'title': 'Практикум: воспроизведение и анализ отчета ThreadSanitizer (-race)', 'task': '**[Каверзный кейс]**: Создай глобальную переменную `counter = 0`. Запусти 1000 горутин, каждая делает `counter++`. Выведи результат (он будет меньше 1000). Запусти программу с флагом `-race`, чтобы увидеть ошибку.', 'theory': 'ThreadSanitizer отслеживает каждое обращение к памяти. Отчет детектора гонок содержит стектрейсы горутин, адреса памяти и точные номера строк конфликтующих операций чтения и записи.', 'step_by_step': '1. Создадим глобальный `var counter int`.\n2. Запустим 1000 горутин.\n3. Запустим с флагом `go run -race main.go`.\n4. Проанализируем структуру предупреждения `WARNING: DATA RACE`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\nvar counter int\n\nfunc main() {\n\tvar wg sync.WaitGroup\n\tconst total = 1000\n\twg.Add(total)\n\n\tfor i := 0; i < total; i++ {\n\t\tgo func() {\n\t\t\tdefer wg.Done()\n\t\t\tcounter++ // Точка конфликта\n\t\t}()\n\t}\n\n\twg.Wait()\n\tfmt.Printf("Итоговое несинхронизированное значение: %d\\n", counter)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# WARNING: DATA RACE\n# Write at 0x... by goroutine ...\n# Previous write at 0x... by goroutine ...\n# Итоговое несинхронизированное значение: 954'}], 'under_the_hood': 'ThreadSanitizer выделяет 4 слова теневой памяти (Shadow Memory) на каждые 8 байт памяти приложения для хранения метаданных синхронизации.', 'pitfalls': 'Детектор гонок не гарантирует нахождение всех гонок в кодовой базе: он обнаруживает только те гонки, которые реально произошли во время конкретного прогона программы/теста.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему флаг -race нельзя включать в продакшен-сборках highload сервисов?»\n**Ответ:** Флаг `-race` увеличивает потребление оперативной памяти в 5–10 раз и замедляет выполнение CPU-инструкций в 2–5 раз из-за непрерывного аудита теневой памяти.'}, {'num': 61, 'title': 'In-Memory БД на базе sync.RWMutex для Read-Heavy нагрузки', 'task': '**Оптимизация чтения с `sync.RWMutex`**: Создайте структуру "База данных в памяти" (под капотом обычная мапа). Напишите методы записи и чтения. Предполагая, что чтение происходит в 99% случаев, а запись — в 1%, используйте `sync.RWMutex`. Продемонстрируйте параллельный вызов методов чтения (`RLock` / `RUnlock`), не блокирующих друг друга.', 'theory': 'При Read-Heavy нагрузке (99% чтений) `sync.RWMutex` обеспечивает максимальную пропускную способность, так как десятки ядер процессора могут одновременно параллельно считывать данные из мапы без взаимных блокировок.', 'step_by_step': '1. Создадим структуру `InMemoryDB struct { mu sync.RWMutex; items map[string]string }`.\n2. Реализуем метод `Read(key string) (string, bool)` с `mu.RLock()`.\n3. Реализуем метод `Write(key, val string)` с `mu.Lock()`.\n4. Запустим 100 параллельных читателей.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype InMemoryDB struct {\n\tmu    sync.RWMutex\n\titems map[string]string\n}\n\nfunc NewInMemoryDB() *InMemoryDB {\n\treturn &InMemoryDB{items: make(map[string]string)}\n}\n\nfunc (db *InMemoryDB) Read(key string) (string, bool) {\n\tdb.mu.RLock()\n\tdefer db.mu.RUnlock()\n\tval, exists := db.items[key]\n\treturn val, exists\n}\n\nfunc (db *InMemoryDB) Write(key, val string) {\n\tdb.mu.Lock()\n\tdefer db.mu.Unlock()\n\tdb.items[key] = val\n}\n\nfunc main() {\n\tdb := NewInMemoryDB()\n\tdb.Write("config:theme", "dark_cyberpunk")\n\n\tvar wg sync.WaitGroup\n\tconst totalReaders = 20\n\n\twg.Add(totalReaders)\n\tfor i := 1; i <= totalReaders; i++ {\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\t\t\tval, _ := db.Read("config:theme")\n\t\t\tif id == 1 || id == 20 {\n\t\t\t\tfmt.Printf("[Читатель #%d] Получил тему: %s\\n", id, val)\n\t\t\t}\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Println("Все параллельные чтения выполнены без единой задержки!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [Читатель #1] Получил тему: dark_cyberpunk\n# [Читатель #20] Получил тему: dark_cyberpunk\n# Все параллельные чтения выполнены без единой задержки!'}], 'under_the_hood': '`RLock()` изменяет атомарный счетчик читателей без блокировки планировщика, позволяя ядрам процессора исполнять код параллельно.', 'pitfalls': 'Обычная `map` в Go вызывает моментальную панику `fatal error: concurrent map read and map write`, если попытаться читать без `RLock` во время записи.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему мапа в Go не потокобезопасна по умолчанию?»\n**Ответ:** Создатели Go решили, что 90% сценариев использования мап происходят в пределах одной горутины. Встраивание мьютекса в каждую мапу замедлило бы абсолютно все операции чтения/записи в однопоточных программах.'}, {'num': 62, 'title': 'Потокобезопасный синглтон подключения к БД через sync.Once', 'task': '**Однократное выполнение (`sync.Once`)**: Напишите потокобезопасный синглтон инициализации подключения к базе данных. Используйте `sync.Once`, чтобы гарантировать, что тяжелая функция инициализации выполнится ровно один раз, даже если её параллельно вызывают 100 горутин.', 'theory': 'Паттерн Singleton (Одиночка) с отложенной инициализацией (Lazy Initialization) в Go реализуется через `sync.Once`. Это гарантирует отсутствие гонок данных при первом обращении и максимальную производительность при всех последующих вызовах.', 'step_by_step': '1. Создадим структуру `DatabaseConnection`.\n2. Создадим `var once sync.Once` и `var instance *DatabaseConnection`.\n3. Реализуем функцию `GetDatabase() *DatabaseConnection`.\n4. Запустим 50 горутин, запрашивающих соединение.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype DatabaseConnection struct {\n\tDSN       string\n\tCreatedAt time.Time\n}\n\nvar (\n\tdbInstance *DatabaseConnection\n\tdbOnce     sync.Once\n)\n\nfunc GetDatabase() *DatabaseConnection {\n\tdbOnce.Do(func() {\n\t\tfmt.Println("[DB INIT] Подключение к PostgreSQL кластеру (строго 1 раз)...")\n\t\ttime.Sleep(25 * time.Millisecond) // Тяжелый сетевой handshake\n\t\tdbInstance = &DatabaseConnection{\n\t\t\tDSN:       "postgres://user:secret@localhost:5432/app",\n\t\t\tCreatedAt: time.Now(),\n\t\t}\n\t})\n\treturn dbInstance\n}\n\nfunc main() {\n\tvar wg sync.WaitGroup\n\tconst totalClients = 50\n\n\twg.Add(totalClients)\n\tfor i := 1; i <= totalClients; i++ {\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\t\t\tconn := GetDatabase()\n\t\t\t_ = conn.DSN\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Printf("Синглтон успешно инициализирован, DSN: %s\\n", GetDatabase().DSN)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [DB INIT] Подключение к PostgreSQL кластеру (строго 1 раз)...\n# Синглтон успешно инициализирован, DSN: postgres://user:secret@localhost:5432/app'}], 'under_the_hood': 'После первого вызова `dbOnce.Do` флаг `done` становится равным 1. Последующие 49 горутин проверяют атомарный флаг и возвращают инстанс без блокировок.', 'pitfalls': 'Не передавайте `sync.Once` по значению, иначе у каждой копии будет свой независимый счетчик вызова.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему реализация Singleton через sync.Once лучше, чем ручной if instance == nil с sync.Mutex?»\n**Ответ:** Потому что в наивной реализации `if instance == nil` без мьютекса возникает Data Race, а с мьютексом `mu.Lock()` захватывается при каждом чтении, замедляя программу. `sync.Once` реализует высокоэффективный паттерн Double-Checked Locking на уровне рантайма.'}, {'num': 63, 'title': 'Высоконагруженный SafeCounter: 1000 горутин по 1000 операций', 'task': 'Реализуй `SafeCounter` с `sync.Mutex`. Методы: `Inc()`, `Dec()`, `Value() int`. Запусти 1000 горутин, каждая инкрементирует 1000 раз. Проверь через `-race`, что гонок нет.', 'theory': 'Тестирование структуры под экстремальной конкуренцией (1 000 000 операций) подтверждает абсолютную надежность механизма `sync.Mutex`.', 'step_by_step': '1. Создадим структуру `SafeCounter`.\n2. Реализуем методы `Inc()`, `Dec()`, `Value() int`.\n3. Запустим 1000 горутин по 1000 инкрементов (всего $1\\,000\\,000$ операций).\n4. Проверим точный результат.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\ntype SafeCounter struct {\n\tmu    sync.Mutex\n\tvalue int\n}\n\nfunc (c *SafeCounter) Inc() {\n\tc.mu.Lock()\n\tc.value++\n\tc.mu.Unlock()\n}\n\nfunc (c *SafeCounter) Dec() {\n\tc.mu.Lock()\n\tc.value--\n\tc.mu.Unlock()\n}\n\nfunc (c *SafeCounter) Value() int {\n\tc.mu.Lock()\n\tdefer c.mu.Unlock()\n\treturn c.value\n}\n\nfunc main() {\n\tcounter := &SafeCounter{}\n\tvar wg sync.WaitGroup\n\n\tconst goroutines = 1000\n\tconst opsPerGoroutine = 1000\n\twg.Add(goroutines)\n\n\tfor i := 0; i < goroutines; i++ {\n\t\tgo func() {\n\t\t\tdefer wg.Done()\n\t\t\tfor j := 0; j < opsPerGoroutine; j++ {\n\t\t\t\tcounter.Inc()\n\t\t\t}\n\t\t}()\n\t}\n\n\twg.Wait()\n\tfmt.Printf("Итоговое значение SafeCounter: %d (из %d)\\n", counter.Value(), goroutines*opsPerGoroutine)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# Итоговое значение SafeCounter: 1000000 (из 1000000)'}], 'under_the_hood': 'Для коротких критических секций `Inc()` прямой вызов `mu.Unlock()` без `defer` работает на доли наносекунд быстрее в горячих циклах.', 'pitfalls': 'При 1M операциях мьютекс создает высокую конкуренцию (contention). В реальных HighLoad счетчиках применяют `atomic` или Sharded Counters.', 'bigtech_interview': '**Вопрос с собеседования:** «Что такое Sharded Counter (Striped Mutex) и зачем он нужен?»\n**Ответ:** Это массив из N независимых счетчиков (например, по числу ядер CPU). Каждая горутина инкрементирует счетчик `shard[hash % N]`, снижая конкуренцию на шине памяти почти до нуля. Итоговая сумма вычисляется суммированием всех шардов.'}, {'num': 64, 'title': 'Рекурсивный вызов метода с Mutex: дедлок и разделение на внутренние методы', 'task': 'Покажи **deadlock с Mutex**: рекурсивный вызов `Lock()` внутри метода с `sync.Mutex` (не `RWMutex`). Получи deadlock. Объясни, почему `sync.Mutex` не reentrant. Исправь через вынесение логики или `sync.RWMutex` (если чтение).', 'theory': 'Так как `sync.Mutex` в Go не реентерабелен, вызов экспортируемого метода `MethodA()` (захватывающего `Lock`) из другого метода `MethodB()` (уже удерживающего `Lock`) вызывает мгновенный дедлок. Идиоматичное решение: разделение на экспортируемый метод с блокировкой и неэкспортируемый внутренний метод `methodLocked()` без блокировки.', 'step_by_step': '1. Объявим внутренний метод `addBonusLocked(bonus int)`.\n2. В публичных методах `AddBonus` и `PromoteWithBonus` захватим мьютекс и вызовем `addBonusLocked`.\n3. Убедимся в отсутствии дедлока.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\ntype Employee struct {\n\tmu     sync.Mutex\n\tsalary int\n\trank   string\n}\n\n// 1. Внутренний неэкспортируемый метод БЕЗ блокировки\nfunc (e *Employee) addBonusLocked(bonus int) {\n\te.salary += bonus\n}\n\n// 2. Публичный метод С блокировкой\nfunc (e *Employee) AddBonus(bonus int) {\n\te.mu.Lock()\n\tdefer e.mu.Unlock()\n\te.addBonusLocked(bonus)\n}\n\n// 3. Комплексный публичный метод, вызывающий внутреннюю логику\nfunc (e *Employee) Promote(newRank string, bonus int) {\n\te.mu.Lock()\n\tdefer e.mu.Unlock()\n\n\te.rank = newRank\n\t// Вызываем внутренний метод без повторного захвата мьютекса\n\te.addBonusLocked(bonus)\n}\n\nfunc main() {\n\temp := &Employee{salary: 100000, rank: "Middle"}\n\n\temp.Promote("Senior", 50000)\n\n\tfmt.Printf("Сотрудник: должность %s, зарплата: %d руб.\\n", emp.rank, emp.salary)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Сотрудник: должность Senior, зарплата: 150000 руб.'}], 'under_the_hood': 'Разделение на `Method()` и `methodLocked()` — канонический паттерн стандартной библиотеки Go (используется в `net/http`, `os/exec`).', 'pitfalls': 'Никогда не вызывайте `addBonusLocked` без предварительного захвата мьютекса во внешнем методе.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы правила именования методов без блокировки в стандартной библиотеке Go?»\n**Ответ:** По соглашению команды Go внутренние методы, предполагающие, что вызывающий код уже держит блокировку мьютекса, именуются с суффиксом `Locked` (например, `getLocked()`, `removeLocked()`).'}, {'num': 65, 'title': 'Полнофункциональная структура SafeMap на базе sync.RWMutex', 'task': 'Реализуй `SafeMap` с `sync.RWMutex`. Методы: `Get(key string) (int, bool)`, `Set(key string, value int)`, `Delete(key string)`. Запусти читателей и писателей. Покажи, что `RLock` позволяет параллельное чтение.', 'theory': '`SafeMap` с `sync.RWMutex` объединяет все базовые CRUD-операции над ассоциативным массивом с разделением уровней блокировки.', 'step_by_step': '1. Создадим структуру `SafeMap[K comparable, V any]` (или `SafeMapInt`).\n2. Реализуем `Get`, `Set`, `Delete`, `Len`.\n3. Запустим конкурентных читателей и писателей.\n4. Проверим с `-race`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\ntype SafeMapInt struct {\n\tmu   sync.RWMutex\n\tdata map[string]int\n}\n\nfunc NewSafeMapInt() *SafeMapInt {\n\treturn &SafeMapInt{data: make(map[string]int)}\n}\n\nfunc (m *SafeMapInt) Get(key string) (int, bool) {\n\tm.mu.RLock()\n\tdefer m.mu.RUnlock()\n\tval, ok := m.data[key]\n\treturn val, ok\n}\n\nfunc (m *SafeMapInt) Set(key string, val int) {\n\tm.mu.Lock()\n\tdefer m.mu.Unlock()\n\tm.data[key] = val\n}\n\nfunc (m *SafeMapInt) Delete(key string) {\n\tm.mu.Lock()\n\tdefer m.mu.Unlock()\n\tdelete(m.data, key)\n}\n\nfunc main() {\n\tsm := NewSafeMapInt()\n\tsm.Set("server:port", 8080)\n\tsm.Set("metrics:rate", 1200)\n\n\tvar wg sync.WaitGroup\n\twg.Add(3)\n\n\t// Читатель 1\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tval, _ := sm.Get("server:port")\n\t\tfmt.Printf("[R1] server:port = %d\\n", val)\n\t}()\n\n\t// Читатель 2\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tval, _ := sm.Get("metrics:rate")\n\t\tfmt.Printf("[R2] metrics:rate = %d\\n", val)\n\t}()\n\n\t// Писатель\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tsm.Set("workers:count", 16)\n\t}()\n\n\twg.Wait()\n\tfmt.Println("Все операции SafeMap выполнены безопасно")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [R1] server:port = 8080\n# [R2] metrics:rate = 1200\n# Все операции SafeMap выполнены безопасно'}], 'under_the_hood': '`delete(m.data, key)` внутри `mu.Lock()` перестраивает бакеты хеш-таблицы без опасности гонок.', 'pitfalls': 'Метод `Delete` обязан использовать эксклюзивный `Lock()`, так как модифицирует структуру бакетов мапы.', 'bigtech_interview': '**Вопрос с собеседования:** «Что произойдет, если вызвать delete() на мапе во время RLock() в другой горутине?»\n**Ответ:** Произойдет немедленная фатальная ошибка рантайма: `fatal error: concurrent map read and map write`. Рантайм Go содержит внутренний флаг `hashWriting` в заголовке `hmap`.'}, {'num': 66, 'title': 'Условные переменные sync.Cond: ожидание события и массовое пробуждение через Broadcast()', 'task': '**Условные переменные (`sync.Cond`)**: Напишите программу, где несколько горутин-воркеров ждут сигнала о готовности данных. Используйте `sync.Cond` с методом `Wait()`. Главная горутина подготавливает данные и будит все воркеры сразу с помощью метода `Broadcast()`.', 'theory': '`sync.Cond` реализует условную переменную (Condition Variable). Воркеры усыпляются в методе `cond.Wait()`, временно освобождая связанный мьютекс. Метод `cond.Broadcast()` пробуждает сразу все ожидающие горутины, а `cond.Signal()` — одну.', 'step_by_step': '1. Создадим `mu := &sync.Mutex{}` и `cond := sync.NewCond(mu)`.\n2. Создадим разделяемую переменную готовности `ready := false`.\n3. Запустим 3 воркера с циклом ожидания `for !ready { cond.Wait() }`.\n4. В `main` установим `ready = true` и вызовем `cond.Broadcast()`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc main() {\n\tvar mu sync.Mutex\n\tcond := sync.NewCond(&mu)\n\tready := false\n\n\tvar wg sync.WaitGroup\n\tconst numWorkers = 3\n\n\t// Запуск воркеров, ожидающих сигнала готовности\n\tfor i := 1; i <= numWorkers; i++ {\n\t\twg.Add(1)\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\n\t\t\tmu.Lock()\n\t\t\t// КРИТИЧЕСКИ ВАЖНО: всегда проверять условие в цикле for, а не if\n\t\t\tfor !ready {\n\t\t\t\tfmt.Printf("[Воркер %d] Ожидание сигнала через cond.Wait()...\\n", id)\n\t\t\t\tcond.Wait() // Освобождает mu и засыпает, при пробуждении снова захватывает mu\n\t\t\t}\n\t\t\tfmt.Printf("[Воркер %d] Сигнал получен! Начинаю обработку данных.\\n", id)\n\t\t\tmu.Unlock()\n\t\t}(i)\n\t}\n\n\ttime.Sleep(20 * time.Millisecond)\n\n\t// Главный поток готовит данные\n\tmu.Lock()\n\tfmt.Println("\\n[Main] Подготовка данных завершена. Отправка Broadcast всем воркерам...")\n\tready = true\n\tcond.Broadcast() // Будит абсолютно все спящие горутины\n\tmu.Unlock()\n\n\twg.Wait()\n\tfmt.Println("[Main] Все воркеры успешно завершили работу!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Воркер 1] Ожидание сигнала через cond.Wait()...\n# [Воркер 2] Ожидание сигнала через cond.Wait()...\n# [Воркер 3] Ожидание сигнала через cond.Wait()...\n# \n# [Main] Подготовка данных завершена. Отправка Broadcast всем воркерам...\n# [Воркер 1] Сигнал получен! Начинаю обработку данных.\n# [Воркер 2] Сигнал получен! Начинаю обработку данных.\n# [Воркер 3] Сигнал получен! Начинаю обработку данных.\n# [Main] Все воркеры успешно завершили работу!'}], 'under_the_hood': '`cond.Wait()` регистрирует горутину в двусвязном списке ожидания `notifyList` и вызывает `goparkunlock`, освобождая мьютекс.', 'pitfalls': 'Всегда проверяйте условие в цикле `for !ready`, а не `if !ready`, из-за риска ложных пробуждений (Spurious Wakeups).', 'bigtech_interview': '**Вопрос с собеседования:** «Почему проверка условия ожидания в sync.Cond всегда должна быть в цикле for, а не if?»\n**Ответ:** 1) Из-за Spurious Wakeups (ложных пробуждений на уровне ОС). 2) Когда `Broadcast()` будит несколько горутин, первая проснувшаяся может забрать ресурс и изменить условие обратно на `ready = false`.'}, {'num': 67, 'title': 'Бенчмарк: sync.Mutex против sync.RWMutex при Read-Heavy сценарии (90/10)', 'task': 'Сравни производительность: `sync.Mutex` vs `sync.RWMutex` при 90% чтений и 10% записей. Замерь `time.Now()` до/после 1M операций. Покажи, что `RWMutex` выигрывает при преобладании чтений.', 'theory': 'При многопоточном чтении `sync.RWMutex` устраняет contention на критической секции: пока нет записи, все читатели выполняют полезную работу одновременно на всех ядрах.', 'step_by_step': '1. Напишем тестовую функцию для `sync.Mutex` и `sync.RWMutex`.\n2. Смоделируем 90% чтений и 10% записей на 100 000 операций.\n3. Замерим время выполнения `time.Since`.\n4. Сравним показатели.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc benchMutex(ops int) time.Duration {\n\tvar mu sync.Mutex\n\tdata := make(map[int]int)\n\tvar wg sync.WaitGroup\n\n\tstart := time.Now()\n\tconst workers = 8\n\twg.Add(workers)\n\n\tfor w := 0; w < workers; w++ {\n\t\tgo func(workerID int) {\n\t\t\tdefer wg.Done()\n\t\t\tfor i := 0; i < ops/workers; i++ {\n\t\t\t\tmu.Lock()\n\t\t\t\tif i%10 == 0 {\n\t\t\t\t\tdata[i%100] = i // 10% записей\n\t\t\t\t} else {\n\t\t\t\t\t_ = data[i%100] // 90% чтений\n\t\t\t\t}\n\t\t\t\tmu.Unlock()\n\t\t\t}\n\t\t}(w)\n\t}\n\n\twg.Wait()\n\treturn time.Since(start)\n}\n\nfunc benchRWMutex(ops int) time.Duration {\n\tvar mu sync.RWMutex\n\tdata := make(map[int]int)\n\tvar wg sync.WaitGroup\n\n\tstart := time.Now()\n\tconst workers = 8\n\twg.Add(workers)\n\n\tfor w := 0; w < workers; w++ {\n\t\tgo func(workerID int) {\n\t\t\tdefer wg.Done()\n\t\t\tfor i := 0; i < ops/workers; i++ {\n\t\t\t\tif i%10 == 0 {\n\t\t\t\t\tmu.Lock()\n\t\t\t\t\tdata[i%100] = i // 10% записей\n\t\t\t\t\tmu.Unlock()\n\t\t\t\t} else {\n\t\t\t\t\tmu.RLock()\n\t\t\t\t\t_ = data[i%100] // 90% чтений\n\t\t\t\t\tmu.RUnlock()\n\t\t\t\t}\n\t\t\t}\n\t\t}(w)\n\t}\n\n\twg.Wait()\n\treturn time.Since(start)\n}\n\nfunc main() {\n\tconst totalOps = 200000\n\n\ttMutex := benchMutex(totalOps)\n\ttRWMutex := benchRWMutex(totalOps)\n\n\tfmt.Printf("Время sync.Mutex   (90%% чтение / 10%% запись): %v\\n", tMutex)\n\tfmt.Printf("Время sync.RWMutex (90%% чтение / 10%% запись): %v\\n", tRWMutex)\n\tfmt.Println("Вывод: RWMutex эффективнее при доминировании операций чтения.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Время sync.Mutex   (90% чтение / 10% запись): 48.32ms\n# Время sync.RWMutex (90% чтение / 10% запись): 21.15ms\n# Вывод: RWMutex эффективнее при доминировании операций чтения.'}], 'under_the_hood': 'При `RLock()` горутины не блокируют системные потоки M, позволяя ядрам процессора обрабатывать запросы без контекстных переключений.', 'pitfalls': 'Если соотношение чтений упадет до 50/50, `sync.Mutex` станет быстрее из-за меньшего оверхеда на кэш-линии.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему RWMutex может деградировать при 64+ ядрах CPU даже при 99% чтении?»\n**Ответ:** Из-за Cache-Line Bouncing: каждый вызов `RLock()` атомарно модифицирует общее поле `readerCount`, инвалидируя кэш-линию L1/L2 во всех 64 ядрах процессора.'}, {'num': 68, 'title': 'Идиоматичная реализация потокобезопасной мапы с методами Get, Set и Delete', 'task': '`sync.RWMutex`: `SafeMap` с методами `Get`, `Set`, `Delete`. Много читателей могут читать одновременно, писатель эксклюзивно.', 'theory': 'Шаблон разделяемого доступа к ресурсу: параллельные читатели и монопольный доступ писателя.', 'step_by_step': '1. Создадим структуру `ConcurrentStorage`.\n2. Реализуем `Get(k string) (string, bool)`, `Set(k, v string)`, `Delete(k string)`.\n3. Запустим сценарий с 10 читателями и 1 писателем.\n4. Проверим согласованность данных.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype ConcurrentStorage struct {\n\tmu    sync.RWMutex\n\tstore map[string]string\n}\n\nfunc NewConcurrentStorage() *ConcurrentStorage {\n\treturn &ConcurrentStorage{store: make(map[string]string)}\n}\n\nfunc (s *ConcurrentStorage) Get(key string) (string, bool) {\n\ts.mu.RLock()\n\tdefer s.mu.RUnlock()\n\tval, ok := s.store[key]\n\treturn val, ok\n}\n\nfunc (s *ConcurrentStorage) Set(key, value string) {\n\ts.mu.Lock()\n\tdefer s.mu.Unlock()\n\ts.store[key] = value\n}\n\nfunc (s *ConcurrentStorage) Delete(key string) {\n\ts.mu.Lock()\n\tdefer s.mu.Unlock()\n\tdelete(s.store, key)\n}\n\nfunc main() {\n\tstorage := NewConcurrentStorage()\n\tstorage.Set("status", "healthy")\n\n\tvar wg sync.WaitGroup\n\twg.Add(4)\n\n\t// Читатели\n\tfor i := 1; i <= 3; i++ {\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\t\t\tval, _ := storage.Get("status")\n\t\t\tfmt.Printf("[Reader %d] status = %s\\n", id, val)\n\t\t}(i)\n\t}\n\n\t// Писатель\n\tgo func() {\n\t\tdefer wg.Done()\n\t\ttime.Sleep(5 * time.Millisecond)\n\t\tstorage.Set("status", "maintenance")\n\t}()\n\n\twg.Wait()\n\tfinalStatus, _ := storage.Get("status")\n\tfmt.Printf("Финальный статус в хранилище: %s\\n", finalStatus)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [Reader 1] status = healthy\n# [Reader 2] status = healthy\n# [Reader 3] status = healthy\n# Финальный статус в хранилище: maintenance'}], 'under_the_hood': '`sync.RWMutex` предотвращает панику рантайма `concurrent map read and map write`.', 'pitfalls': 'Не забывайте `defer s.mu.RUnlock()` в методе `Get`.', 'bigtech_interview': '**Вопрос с собеседования:** «Можно ли вернуть из SafeMap указатель на структуру и модифицировать её поля снаружи?»\n**Ответ:** НЕТ! Возврат указателя нарушает инкапсуляцию потокобезопасности: внешний код сможет мутировать поля структуры без захвата мьютекса, создавая Data Race. Нужно возвращать копию структуры по значению.'}, {'num': 69, 'title': 'Управление жизненным циклом сервиса через atomic.LoadInt64 и StoreInt64', 'task': 'Используйте `atomic.LoadInt64` и `atomic.StoreInt64` для потокобезопасного чтения и записи флагов состояния (например, `isRunning`).', 'theory': 'Использование атомарных операций `atomic.LoadInt64` / `atomic.StoreInt64` (или `atomic.Int64`) позволяет реализовывать флаги состояния сервиса (0 = Stopped, 1 = Running, 2 = Draining) с максимальной производительностью без захвата тяжелых мьютексов.', 'step_by_step': '1. Создадим структуру `ServiceState` с `status int64`.\n2. Реализуем методы `SetRunning()`, `SetStopped()`, `IsRunning() bool`.\n3. Запустим фоновый цикл воркера.\n4. В `main` изменим состояние и дождемся остановки.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"sync/atomic"\n\t"time"\n)\n\nconst (\n\tStateStopped = 0\n\tStateRunning = 1\n)\n\ntype WorkerService struct {\n\tstate int64\n}\n\nfunc (s *WorkerService) Start() {\n\tatomic.StoreInt64(&s.state, StateRunning)\n}\n\nfunc (s *WorkerService) Stop() {\n\tatomic.StoreInt64(&s.state, StateStopped)\n}\n\nfunc (s *WorkerService) IsRunning() bool {\n\treturn atomic.LoadInt64(&s.state) == StateRunning\n}\n\nfunc main() {\n\tservice := &WorkerService{}\n\tservice.Start()\n\n\tvar wg sync.WaitGroup\n\twg.Add(1)\n\n\t// Фоновый процесс\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tfmt.Println("[Service] Сервис запущен и обрабатывает события...")\n\t\tticks := 0\n\t\tfor service.IsRunning() {\n\t\t\tticks++\n\t\t\ttime.Sleep(10 * time.Millisecond)\n\t\t}\n\t\tfmt.Printf("[Service] Сервис корректно остановлен (обработано тиков: %d)\\n", ticks)\n\t}()\n\n\ttime.Sleep(35 * time.Millisecond)\n\tfmt.Println("[Main] Отправка команды Stop()...")\n\tservice.Stop()\n\n\twg.Wait()\n\tfmt.Println("[Main] Сервис успешно завершил жизненный цикл")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [Service] Сервис запущен и обрабатывает события...\n# [Main] Отправка команды Stop()...\n# [Service] Сервис корректно остановлен (обработано тиков: 3)\n# [Main] Сервис успешно завершил жизненный цикл'}], 'under_the_hood': '`atomic.StoreInt64` генерирует барьер памяти (Memory Barrier), гарантируя, что все предшествующие записи в память станут видны другим ядрам CPU до обновления флага.', 'pitfalls': 'На 32-битных архитектурах `int64` должен быть строго выровнен по 8-байтной границе.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему чтение незащищенной переменной bool в цикле for running {} может привести к бесконечному зависанию?»\n**Ответ:** Компилятор Go при оптимизации (SSA) помещает переменную `running` в регистр процессора один раз перед циклом. Изменение переменной в памяти из другой горутины никогда не обновит этот регистр, и горутина зависнет в вечном цикле.'}, {'num': 70, 'title': 'Конкурентная мапа sync.Map: Store, Load, Delete и итерация Range', 'task': 'Используй `sync.Map` для хранения `map[string]int`. Запусти конкурентные чтения/записи. Покажи, что `sync.Map` безопасен без ручного mutex. Напиши `Range` с `func(key, value any) bool`.', 'theory': '`sync.Map` — это специализированная потокобезопасная коллекция стандартной библиотеки Go. Она оптимизирована для двух сценариев: 1) Ключ записывается один раз, но читается многократно (кэш), 2) Множество горутин читают, записывают и перезаписывают непересекающиеся множества ключей.', 'step_by_step': '1. Создадим переменную `var sm sync.Map`.\n2. Запустим горутины с вызовами `sm.Store("key", val)`.\n3. Считаем значение через `val, ok := sm.Load("key")`.\n4. Обойдем все элементы через `sm.Range(func(key, value any) bool { ... })`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\nfunc main() {\n\tvar sm sync.Map\n\tvar wg sync.WaitGroup\n\n\t// Конкурентная запись\n\tconst items = 5\n\twg.Add(items)\n\tfor i := 1; i <= items; i++ {\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\t\t\tkey := fmt.Sprintf("metric_%d", id)\n\t\t\tsm.Store(key, id*100)\n\t\t}(i)\n\t}\n\twg.Wait()\n\n\t// Чтение конкретного ключа\n\tif val, ok := sm.Load("metric_3"); ok {\n\t\tfmt.Printf("Успешно прочитано: metric_3 = %v\\n", val)\n\t}\n\n\t// Итерация по всем ключам через Range\n\tfmt.Println("\\nИтерация по sync.Map:")\n\tsm.Range(func(key, value any) bool {\n\t\tfmt.Printf(" -> %s = %d\\n", key.(string), value.(int))\n\t\treturn true // true = продолжить итерацию, false = прервать\n\t})\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# Успешно прочитано: metric_3 = 300\n# \n# Итерация по sync.Map:\n#  -> metric_1 = 100\n#  -> metric_2 = 200\n#  -> metric_3 = 300\n#  -> metric_4 = 400\n#  -> metric_5 = 500'}], 'under_the_hood': '`sync.Map` состоит из двух внутренних мап: `read` (lock-free атомарный `atomic.Value` для быстрого чтения) и `dirty` (требует мьютекс для записи новых ключей).', 'pitfalls': '`sync.Map` оперирует типом `any`, что требует явных приведений типов (`key.(string)`). Для типизированного кода в Go 1.18+ часто предпочитают обертки над `map[K]V` с `sync.RWMutex`.', 'bigtech_interview': '**Вопрос с собеседования:** «Когда НЕ следует использовать sync.Map?»\n**Ответ:** Когда программа часто добавляет и удаляет произвольные ключи (Write-Heavy сценарий). В этом случае `dirty` мапа постоянно копируется и блокируется мьютексом, из-за чего обычная `map + sync.RWMutex` работает в 2–3 раза быстрее.'}, {'num': 71, 'title': 'Архитектурное сравнение: sync.Map против map + sync.RWMutex', 'task': 'Сравни `sync.Map` и `map + sync.RWMutex` по производительности. Напиши бенчмарк (`testing.B`). Покажи, что `sync.Map` оптимизирован под **read-mostly** сценарии с редкими записами, а для write-heavy — обычная map + mutex быстрее.', 'theory': '`sync.Map` выигрывает только при Read-Heavy нагрузке (благодаря lock-free чтению из `read`). При частых записях новых ключей (Write-Heavy) `sync.Map` страдает от постоянного промоушена `dirty -> read` и копирования мап.', 'step_by_step': '1. Напишем сравнительный тест производительности.\n2. Протестируем сценарий 95% чтений (Read-Heavy).\n3. Протестируем сценарий 100% записей новых ключей (Write-Heavy).\n4. Проанализируем замеры времени.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\nfunc benchSyncMap(totalOps int) time.Duration {\n\tvar sm sync.Map\n\tfor i := 0; i < 100; i++ {\n\t\tsm.Store(i, i)\n\t}\n\n\tstart := time.Now()\n\tvar wg sync.WaitGroup\n\twg.Add(4)\n\n\tfor w := 0; w < 4; w++ {\n\t\tgo func() {\n\t\t\tdefer wg.Done()\n\t\t\tfor i := 0; i < totalOps/4; i++ {\n\t\t\t\t// 95% чтений\n\t\t\t\tif i%20 == 0 {\n\t\t\t\t\tsm.Store(i%100, i)\n\t\t\t\t} else {\n\t\t\t\t\t_, _ = sm.Load(i % 100)\n\t\t\t\t}\n\t\t\t}\n\t\t}()\n\t}\n\n\twg.Wait()\n\treturn time.Since(start)\n}\n\nfunc benchRWMutexMap(totalOps int) time.Duration {\n\tvar mu sync.RWMutex\n\tm := make(map[int]int)\n\tfor i := 0; i < 100; i++ {\n\t\tm[i] = i\n\t}\n\n\tstart := time.Now()\n\tvar wg sync.WaitGroup\n\twg.Add(4)\n\n\tfor w := 0; w < 4; w++ {\n\t\tgo func() {\n\t\t\tdefer wg.Done()\n\t\t\tfor i := 0; i < totalOps/4; i++ {\n\t\t\t\tif i%20 == 0 {\n\t\t\t\t\tmu.Lock()\n\t\t\t\t\tm[i%100] = i\n\t\t\t\t\tmu.Unlock()\n\t\t\t\t} else {\n\t\t\t\t\tmu.RLock()\n\t\t\t\t\t_ = m[i%100]\n\t\t\t\t\tmu.RUnlock()\n\t\t\t\t}\n\t\t\t}\n\t\t}()\n\t}\n\n\twg.Wait()\n\treturn time.Since(start)\n}\n\nfunc main() {\n\tconst ops = 500000\n\n\ttSyncMap := benchSyncMap(ops)\n\ttRWMutex := benchRWMutexMap(ops)\n\n\tfmt.Printf("Время sync.Map (Read-Mostly):        %v\\n", tSyncMap)\n\tfmt.Printf("Время map + sync.RWMutex (Read-Mostly): %v\\n", tRWMutex)\n\tfmt.Println("sync.Map демонстрирует превосходную масштабируемость на многоядерных CPU при чтении.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Время sync.Map (Read-Mostly):        14.22ms\n# Время map + sync.RWMutex (Read-Mostly): 28.65ms\n# sync.Map демонстрирует превосходную масштабируемость на многоядерных CPU при чтении.'}], 'under_the_hood': 'Lock-free чтение в `sync.Map` не вызывает Cache-Line Bouncing, масштабируясь линейно по числу ядер.', 'pitfalls': 'Никогда не используйте `sync.Map` в качестве замены обычной мапе в однопоточном коде.', 'bigtech_interview': '**Вопрос с собеседования:** «Каковы два ключевых use-case для sync.Map по официальной документации Go?»\n**Ответ:** 1) Когда запись каждого ключа происходит ровно один раз, а чтение — многократно (кеширование стабильных структур). 2) Когда разные горутины работают с непересекающимися наборами ключей (Disjoint Sets).'}, {'num': 72, 'title': 'Инициализация дорогого ресурса из файла строго один раз через sync.Once', 'task': '`sync.Once`: инициализация дорогого ресурса (например, чтение конфигурации из файла) только один раз при конкурентных вызовах.', 'theory': '`sync.Once` обеспечивает строгую линеаризацию: даже если 100 горутин одновременно обращаются к методу инициализации, чтение файла произойдет ровно 1 раз, а остальные 99 горутин дождутся завершения чтения и безопасно получат готовый результат.', 'step_by_step': '1. Создадим структуру `CertStore`.\n2. Реализуем метод `LoadCertificates()` с `sync.Once`.\n3. Смоделируем обращение 10 параллельных клиентов.\n4. Убедимся, что загрузка файла произошла единожды.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype TLSManager struct {\n\tonce      sync.Once\n\tcertChain string\n}\n\nfunc (m *TLSManager) GetCertificate() string {\n\tm.once.Do(func() {\n\t\tfmt.Println("[DISK I/O] Чтение тяжелых TLS-сертификатов с диска...")\n\t\ttime.Sleep(30 * time.Millisecond) // Дорогой парсинг x509\n\t\tm.certChain = "BEGIN CERTIFICATE: RSA 4096 VALID"\n\t})\n\treturn m.certChain\n}\n\nfunc main() {\n\tmanager := &TLSManager{}\n\tvar wg sync.WaitGroup\n\n\tconst clients = 5\n\twg.Add(clients)\n\n\tfor i := 1; i <= clients; i++ {\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\t\t\tcert := manager.GetCertificate()\n\t\t\tfmt.Printf("[Клиент #%d] Сертификат получен: %s\\n", id, cert)\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Println("Инициализация TLS успешно завершена!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [DISK I/O] Чтение тяжелых TLS-сертификатов с диска...\n# [Клиент #1] Сертификат получен: BEGIN CERTIFICATE: RSA 4096 VALID\n# [Клиент #2] Сертификат получен: BEGIN CERTIFICATE: RSA 4096 VALID\n# [Клиент #3] Сертификат получен: BEGIN CERTIFICATE: RSA 4096 VALID\n# [Клиент #4] Сертификат получен: BEGIN CERTIFICATE: RSA 4096 VALID\n# [Клиент #5] Сертификат получен: BEGIN CERTIFICATE: RSA 4096 VALID\n# Инициализация TLS успешно завершена!'}], 'under_the_hood': '`sync.Once` содержит барьер памяти `atomic.StoreUint32(&o.done, 1)`, гарантируя видимость всех полей структуры `TLSManager` всем ядрам CPU.', 'pitfalls': 'Не вызывайте `m.GetCertificate()` рекурсивно внутри замыкания `once.Do` — это приведет к дедлоку.', 'bigtech_interview': '**Вопрос с собеседования:** «Что будет, если вызвать once.Do внутри другого once.Do для того же самого объекта once?»\n**Ответ:** Произойдет классический дедлок (Deadlock), так как внутренний вызов `once.Do` попытается захватить мьютекс `o.m`, уже удерживаемый внешним вызовом `once.Do`.'}, {'num': 73, 'title': 'Устранение паники concurrent map writes: переход 50 горутин на sync.Map', 'task': '**Потокобезопасная мапа (`sync.Map`)**: Напишите программу, где 50 горутин параллельно пишут и читают данные из одной мапы. Обычная мапа упадет с паникой `concurrent map writes`. Решите эту проблему с помощью встроенной структуры `sync.Map` и её методов `Store`, `Load` и `Delete`.', 'theory': 'Обычная мапа в Go не содержит встроенных средств синхронизации. При параллельной записи двух горутин рантайм вызывает аварийное падение приложения `fatal error: concurrent map writes`. `sync.Map` решает эту проблему "из коробки".', 'step_by_step': '1. Создадим `var sm sync.Map`.\n2. Запустим 50 горутин, одновременно выполняющих `Store`, `Load` и `Delete`.\n3. Дождемся завершения всех горутин через `sync.WaitGroup`.\n4. Убедимся в абсолютной стабильности под флагом `-race`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\nfunc main() {\n\tvar sm sync.Map\n\tvar wg sync.WaitGroup\n\n\tconst totalWorkers = 50\n\twg.Add(totalWorkers)\n\n\tfor i := 0; i < totalWorkers; i++ {\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\n\t\t\t// 1. Запись\n\t\t\tkey := fmt.Sprintf("session:%d", id%10)\n\t\t\tsm.Store(key, id*10)\n\n\t\t\t// 2. Чтение\n\t\t\t_, _ = sm.Load(key)\n\n\t\t\t// 3. Удаление\n\t\t\tif id%5 == 0 {\n\t\t\t\tsm.Delete(key)\n\t\t\t}\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Println("Все 50 горутин успешно выполнили параллельные операции над sync.Map без сбоев!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# Все 50 горутин успешно выполнили параллельные операции над sync.Map без сбоев!'}], 'under_the_hood': 'Метод `Store` обновляет существующий ключ lock-free, если он уже присутствует в `read` мапе и не помечен как `expunged`.', 'pitfalls': 'В `sync.Map` метод `LoadOrStore(key, val)` атомарен: он возвращает существующее значение, если ключ был, или сохраняет переданное, исключая гонки повторной инициализации.', 'bigtech_interview': '**Вопрос с собеседования:** «Что делает метод LoadOrStore в sync.Map?»\n**Ответ:** Атомарно загружает существующее значение для ключа или сохраняет переданное, если ключа не было. Возвращает `(actual any, loaded bool)`, где `loaded == true` означает, что значение уже присутствовало в мапе.'}, {'num': 74, 'title': 'Ленивая инициализация Singleton через sync.Once в GetInstance()', 'task': 'Используй `sync.Once` для **lazy initialization**: `var once sync.Once; var instance *Singleton`. Функция `GetInstance()` вызывает `once.Do(func() { instance = &Singleton{} })`. Покажи, что инициализация происходит ровно один раз, даже при конкурентных вызовах.', 'theory': 'Паттерн Lazy Singleton откладывает создание объекта до первого реального обращения к нему. `sync.Once` защищает от гонки создания дубликатов.', 'step_by_step': '1. Создадим структуру `AnalyticsEngine`.\n2. Создадим `var instance *AnalyticsEngine` и `var once sync.Once`.\n3. Реализуем функцию `GetAnalytics() *AnalyticsEngine`.\n4. Запустим параллельные вызовы из 20 горутин.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\ntype AnalyticsEngine struct {\n\tSessionID string\n}\n\nvar (\n\tanalyticsInstance *AnalyticsEngine\n\tanalyticsOnce     sync.Once\n)\n\nfunc GetAnalytics() *AnalyticsEngine {\n\tanalyticsOnce.Do(func() {\n\t\tfmt.Println("[SINGLETON] Первичная инициализация AnalyticsEngine...")\n\t\tanalyticsInstance = &AnalyticsEngine{\n\t\t\tSessionID: "sess_global_9921",\n\t\t}\n\t})\n\treturn analyticsInstance\n}\n\nfunc main() {\n\tvar wg sync.WaitGroup\n\tconst callers = 20\n\n\twg.Add(callers)\n\tfor i := 1; i <= callers; i++ {\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\t\t\teng := GetAnalytics()\n\t\t\tif id == 1 || id == 20 {\n\t\t\t\tfmt.Printf("[Caller #%d] Получен инстанс: %s\\n", id, eng.SessionID)\n\t\t\t}\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Println("Синглтон успешно распределен между всеми клиентами!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# [SINGLETON] Первичная инициализация AnalyticsEngine...\n# [Caller #1] Получен инстанс: sess_global_9921\n# [Caller #20] Получен инстанс: sess_global_9921\n# Синглтон успешно распределен между всеми клиентами!'}], 'under_the_hood': '`analyticsOnce.Do` гарантирует, что горутина не получит указатель `analyticsInstance` до тех пор, пока поля структуры полностью не проинициализируются.', 'pitfalls': 'В юнит-тестах синглтоны сложно сбрасывать между тестами. Для тестирования лучше передавать зависимости через Dependency Injection (интерфейсы).', 'bigtech_interview': '**Вопрос с собеседования:** «Можно ли сбросить состояние sync.Once, чтобы переинициализировать синглтон?»\n**Ответ:** Стандартного метода `Reset()` в `sync.Once` нет. Для переинициализации создают новый экземпляр `once = sync.Once{}` под внешней блокировкой `sync.Mutex`.'}, {'num': 75, 'title': 'Практикум: детальный разбор структуры логов детектора гонок ThreadSanitizer', 'task': '**Детектор гонок**: Запусти код из 282 с флагом `go run -race`. Изучи красный пугающий лог "WARNING: DATA RACE".', 'theory': 'Отчет `WARNING: DATA RACE` состоит из 4 ключевых секций:\n1. Тип операции и адрес ячейки памяти (`Read at 0x... by goroutine X`).\n2. Стектрейс конфликтующего чтения (файл, строка, функция).\n3. Тип и стектрейс предшествующей несогласованной записи (`Previous write at 0x... by goroutine Y`).\n4. Точка создания конфликтующих горутин (`Goroutine X created at...`).', 'step_by_step': '1. Создадим намеренную гонку между чтением и записью.\n2. Запустим программу с флагом `-race`.\n3. Построчно разберем вывод детектора.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"time"\n)\n\nfunc main() {\n\tmessage := "Начальное значение"\n\n\t// Горутина 1: Запись\n\tgo func() {\n\t\tmessage = "Записано горутиной 1"\n\t}()\n\n\t// Горутина 2: Чтение без синхронизации\n\tgo func() {\n\t\tfmt.Println("Прочитано:", message)\n\t}()\n\n\ttime.Sleep(20 * time.Millisecond)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод детектора гонок:\n# ==================\n# WARNING: DATA RACE\n# Read at 0x00c000022070 by goroutine 8:\n#   main.main.func2()\n#       /home/ut/work/go-workout/main.go:19 +0x38\n# \n# Previous write at 0x00c000022070 by goroutine 7:\n#   main.main.func1()\n#       /home/ut/work/go-workout/main.go:14 +0x3c\n# \n# Goroutine 8 (running) created at:\n#   main.main()\n#       /home/ut/work/go-workout/main.go:18 +0x88\n# \n# Goroutine 7 (finished) created at:\n#   main.main()\n#       /home/ut/work/go-workout/main.go:13 +0x64\n# ==================\n# Прочитано: Записано горутиной 1'}], 'under_the_hood': 'TSan внедряет перехватчики `__tsan_read8` и `__tsan_write8` на каждую инструкцию работы с памятью.', 'pitfalls': 'Никогда не игнорируйте предупреждения `-race`, даже если программа "кажется работающей". Гонки данных в Go могут приводить к повреждению памяти рантайма.', 'bigtech_interview': '**Вопрос с собеседования:** «Может ли флаг -race давать ложноположительные срабатывания (False Positives)?»\n**Ответ:** Нет! ThreadSanitizer в Go математически строг и не выдает False Positives. Если `-race` выдал отчет, значит реальный конфликт параллельного доступа к памяти без Happens-Before отношения гарантированно имел место.'}, {'num': 76, 'title': 'Поведение sync.Once при панике: фиксация статуса выполнения', 'task': 'Покажи, что `sync.Once` **не сбрасывается**: если `Do` паникует, `Once` считает выполненным и повторно не вызовет функцию. Напиши программу, демонстрирующую это (используй `recover` внутри `Do`).', 'theory': 'Если функция, переданная в `once.Do(fn)`, вызывает панику, `sync.Once` гарантирует, что паника раскрутит стек, но статус `done` все равно останется установленным в `1`. Все последующие вызовы `once.Do` будут моментально возвращать управление без повторной попытки выполнить `fn`.', 'step_by_step': '1. Создадим `var once sync.Once`.\n2. Вызовем `once.Do` с функцией, вызывающей панику.\n3. Перехватим панику через `recover()`.\n4. Вызовем `once.Do` повторно с нормальной функцией и покажем, что она не запустилась.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\nfunc main() {\n\tvar once sync.Once\n\n\t// 1. Первый вызов с паникой\n\tfunc() {\n\t\tdefer func() {\n\t\t\tif r := recover(); r != nil {\n\t\t\t\tfmt.Printf("1. Перехвачена паника первого вызова: %v\\n", r)\n\t\t\t}\n\t\t}()\n\n\t\tonce.Do(func() {\n\t\t\tfmt.Println("2. Запуск функции с паникой...")\n\t\t\tpanic("критический сбой внутри once.Do")\n\t\t})\n\t}()\n\n\t// 2. Повторная попытка вызвать once.Do\n\tfmt.Println("3. Попытка повторного вызова once.Do с полезной функцией...")\n\texecuted := false\n\tonce.Do(func() {\n\t\texecuted = true\n\t\tfmt.Println("ЭТА ФУНКЦИЯ НЕ БУДЕТ ВЫЗВАНА")\n\t})\n\n\tfmt.Printf("4. Флаг выполнения второй функции: %v (Once запомнил выполнение, несмотря на панику!)\\n", executed)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 2. Запуск функции с паникой...\n# 1. Перехвачена паника первого вызова: критический сбой внутри once.Do\n# 3. Попытка повторного вызова once.Do с полезной функцией...\n# 4. Флаг выполнения второй функции: false (Once запомнил выполнение, несмотря на панику!)'}], 'under_the_hood': 'Внутри `sync.Once.doSlow` установка `atomic.StoreUint32(&o.done, 1)` выполняется внутри оператора `defer`, что гарантирует её срабатывание даже при панике.', 'pitfalls': 'Если вам требуется повторять инициализацию при ошибках, используйте кастомную обертку с `sync.Mutex` или сторонний пакет `sync/erronce`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему sync.Once не откатывает свое состояние при панике?»\n**Ответ:** Потому что паника означает непредвиденный сбой. Если бы `sync.Once` откатывался, последующие горутины бесконечно паниковали бы в цикле, вызывая каскадный отказ системы (Thundering Herd / Panic Storm).'}, {'num': 77, 'title': 'Оптимизация строкового форматирования с sync.Pool и обязательным defer Put', 'task': 'Используй `sync.Pool` для переиспользования `bytes.Buffer`. Напиши функцию, которая берёт буфер из пула, пишет в него, возвращает строку, и **обязательно** возвращает буфер в пул через `defer`. Покажи снижение аллокаций.', 'theory': 'Паттерн использования `sync.Pool` для временных буферов:\n1. `buf := pool.Get().(*bytes.Buffer)`\n2. `buf.Reset()`\n3. `defer pool.Put(buf)`\n4. Выполнение записи и получение результата.', 'step_by_step': '1. Создадим глобальный `sync.Pool` для `bytes.Buffer`.\n2. Напишем функцию `BuildLogRecord(service string, code int) string`.\n3. Протестируем вызов из нескольких горутин.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bytes"\n\t"fmt"\n\t"sync"\n)\n\nvar stringBufferPool = sync.Pool{\n\tNew: func() any {\n\t\treturn new(bytes.Buffer)\n\t},\n}\n\nfunc BuildLogRecord(service string, status int, latencyMs float64) string {\n\tbuf := stringBufferPool.Get().(*bytes.Buffer)\n\tbuf.Reset() // Очищаем буфер от данных предыдущего использования\n\tdefer stringBufferPool.Put(buf) // Гарантированный возврат в пул\n\n\tfmt.Fprintf(buf, "[AUDIT] service=%s status=%d latency=%.2fms", service, status, latencyMs)\n\treturn buf.String()\n}\n\nfunc main() {\n\tvar wg sync.WaitGroup\n\tconst requests = 5\n\n\twg.Add(requests)\n\tfor i := 1; i <= requests; i++ {\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\t\t\tlogLine := BuildLogRecord("payment-gateway", 200, float64(id)*1.5)\n\t\t\tfmt.Println(" ->", logLine)\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Println("Все логи сформированы с минимальными аллокациями памяти!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n#  -> [AUDIT] service=payment-gateway status=200 latency=1.50ms\n#  -> [AUDIT] service=payment-gateway status=200 latency=3.00ms\n#  -> [AUDIT] service=payment-gateway status=200 latency=4.50ms\n#  -> [AUDIT] service=payment-gateway status=200 latency=6.00ms\n#  -> [AUDIT] service=payment-gateway status=200 latency=7.50ms\n# Все логи сформированы с минимальными аллокациями памяти!'}], 'under_the_hood': '`buf.Reset()` устанавливает `buf.buf = buf.buf[:0]`, сохраняя выделенную базовую емкость слайса `cap` для последующих записей без повторных `malloc`.', 'pitfalls': 'Если в буфер однажды записали 100 МБ данных, он навсегда останется в пуле гигантского размера. В продакшене перед `Put` проверяют `if buf.Cap() <= maxCap { pool.Put(buf) }`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как бороться с проблемой раздувания памяти (Buffer Bloat) в sync.Pool?»\n**Ответ:** Проверять емкость объекта перед возвратом в пул. Если `buf.Cap() > 64*1024` (64 КБ), не вызывать `pool.Put(buf)`, позволяя сборщику мусора утилизировать аномально большой буфер.'}, {'num': 78, 'title': 'Очередь задач с ожиданием через sync.Cond и сигналы Signal()', 'task': '`sync.Cond`: реализуйте очередь задач с ожиданием: горутины ждут `Cond.Wait()`, пока не появятся задачи. Поставщик вызывает `Signal()`.', 'theory': 'Паттерн Producer-Consumer на базе `sync.Cond`: поставщик (Producer) добавляет элемент в очередь и будит одного спящего потребителя методом `cond.Signal()`. Если очередь пуста, потребители (Consumers) спят без расхода CPU в методе `cond.Wait()`.', 'step_by_step': '1. Создадим структуру `TaskQueue` с `sync.Mutex`, `*sync.Cond` и срезом задач `[]string`.\n2. Реализуем метод `Push(task string)` с вызовом `cond.Signal()`.\n3. Реализуем метод `Pop() string` с циклом ожидания `for len(q.tasks) == 0 { cond.Wait() }`.\n4. Запустим 2 воркера и отправим им задачи.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype TaskQueue struct {\n\tmu    sync.Mutex\n\tcond  *sync.Cond\n\ttasks []string\n}\n\nfunc NewTaskQueue() *TaskQueue {\n\tq := &TaskQueue{}\n\tq.cond = sync.NewCond(&q.mu)\n\treturn q\n}\n\nfunc (q *TaskQueue) Push(task string) {\n\tq.mu.Lock()\n\tdefer q.mu.Unlock()\n\n\tq.tasks = append(q.tasks, task)\n\t// Будим ровно одного ожидающего воркера\n\tq.cond.Signal()\n}\n\nfunc (q *TaskQueue) Pop(workerID int) string {\n\tq.mu.Lock()\n\tdefer q.mu.Unlock()\n\n\tfor len(q.tasks) == 0 {\n\t\tfmt.Printf("[Worker #%d] Очередь пуста, засыпаю в cond.Wait()...\\n", workerID)\n\t\tq.cond.Wait()\n\t}\n\n\ttask := q.tasks[0]\n\tq.tasks = q.tasks[1:]\n\treturn task\n}\n\nfunc main() {\n\tqueue := NewTaskQueue()\n\tvar wg sync.WaitGroup\n\n\t// Запуск 2 воркеров\n\tfor w := 1; w <= 2; w++ {\n\t\twg.Add(1)\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\t\t\tfor i := 0; i < 2; i++ {\n\t\t\t\ttask := queue.Pop(id)\n\t\t\t\tfmt.Printf("   -> [Worker #%d] Обработал: %s\\n", id, task)\n\t\t\t}\n\t\t}(w)\n\t}\n\n\ttime.Sleep(20 * time.Millisecond)\n\n\t// Поставщик добавляет 4 задачи\n\tfmt.Println("\\n[Producer] Добавление 4 задач в очередь:")\n\tfor i := 1; i <= 4; i++ {\n\t\tqueue.Push(fmt.Sprintf("Job #%d", i))\n\t\ttime.Sleep(5 * time.Millisecond)\n\t}\n\n\twg.Wait()\n\tfmt.Println("\\n[Main] Все задачи из очереди успешно обработаны!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Worker #1] Очередь пуста, засыпаю в cond.Wait()...\n# [Worker #2] Очередь пуста, засыпаю в cond.Wait()...\n# \n# [Producer] Добавление 4 задач в очередь:\n#    -> [Worker #1] Обработал: Job #1\n#    -> [Worker #2] Обработал: Job #2\n#    -> [Worker #1] Обработал: Job #3\n#    -> [Worker #2] Обработал: Job #4\n# \n# [Main] Все задачи из очереди успешно обработаны!'}], 'under_the_hood': '`cond.Signal()` пробуждает первую горутину в списке ожидания `notifyList` с наименьшим `ticket` номером.', 'pitfalls': 'Вызов `cond.Signal()` или `cond.Broadcast()` без заблокированного мьютекса разрешен спецификацией, но вызов `cond.Wait()` без предварительного `mu.Lock()` немедленно паникует.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие cond.Signal() от cond.Broadcast()?»\n**Ответ:** `Signal()` пробуждает ровно одну горутину из очереди ожидания (FIFO). `Broadcast()` пробуждает абсолютно все горутины, заблокированные в данный момент на `cond.Wait()`.'}, {'num': 79, 'title': 'Счетчик на 1 000 000 инкрементов с защитой sync.Mutex', 'task': '**Исправление через `sync.Mutex`**: Добавь мьютекс. Делай `mu.Lock()` перед инкрементом и `mu.Unlock()` после. Убедись, что счетчик равен миллиону и `-race` молчит.', 'theory': 'Экстремальный тест параллельности: 100 горутин по 10 000 операций инкремента через `sync.Mutex` гарантирует точное сохранение всех $1\\,000\\,000$ значений.', 'step_by_step': '1. Создадим переменную `var total int` и `var mu sync.Mutex`.\n2. Запустим 100 горутин, выполняющих по 10 000 инкрементов.\n3. Обернем `total++` в `mu.Lock()` и `mu.Unlock()`.\n4. Проверим с флагом `-race`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\nfunc main() {\n\tvar total int\n\tvar mu sync.Mutex\n\tvar wg sync.WaitGroup\n\n\tconst numWorkers = 100\n\tconst iterations = 10000\n\n\twg.Add(numWorkers)\n\tfor i := 0; i < numWorkers; i++ {\n\t\tgo func() {\n\t\t\tdefer wg.Done()\n\t\t\tfor j := 0; j < iterations; j++ {\n\t\t\t\tmu.Lock()\n\t\t\t\ttotal++\n\t\t\t\tmu.Unlock()\n\t\t\t}\n\t\t}()\n\t}\n\n\twg.Wait()\n\tfmt.Printf("Итоговый счетчик: %d (ровно %d)\\n", total, numWorkers*iterations)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run -race main.go\n# Вывод:\n# Итоговый счетчик: 1000000 (ровно 1000000)'}], 'under_the_hood': '`mu.Lock()` и `Unlock()` выполняют неделимые атомарные операции синхронизации шины процессора.', 'pitfalls': 'Внутри горячего цикла `for` не используйте `defer mu.Unlock()` — это создает миллион стековых записей `defer`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в цикле for на 10 000 итераций defer mu.Unlock() хуже явного mu.Unlock()?»\n**Ответ:** Потому что `defer` привязан к завершению всей функции, а не к итерации цикла. Использование `defer` внутри цикла оставит мьютекс заблокированным до конца функции и вызовет переполнение стека defer-записей.'}, {'num': 80, 'title': 'Переиспользование тяжелых структур Buffer через sync.Pool для снижения пауз GC', 'task': '**Пул объектов (`sync.Pool`)**: Создайте структуру `Buffer` большого размера. Напишите код, который часто создает и уничтожает эти буферы, перегружая сборщик мусора (GC). Оптимизируйте программу, используя `sync.Pool` для переиспользования выделенной памяти под буферы.', 'theory': 'Постоянное создание больших структур (например, буферов по 1 МБ) заставляет сборщик мусора Go непрерывно запускать фазы Mark-and-Sweep. `sync.Pool` переиспользует уже выделенные слайсы памяти, сокращая нагрузку на аллокатор mcache/mcentral.', 'step_by_step': '1. Создадим тяжелую структуру `LargePacket struct { Payload [64 * 1024]byte; Length int }`.\n2. Настроим `sync.Pool`.\n3. Запустим обработку 100 пакетов с переиспользованием.\n4. Проверим стабильность памяти.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n)\n\ntype LargePacket struct {\n\tPayload [64 * 1024]byte // 64 КБ на объект\n\tLength  int\n}\n\nvar packetPool = sync.Pool{\n\tNew: func() any {\n\t\treturn new(LargePacket)\n\t},\n}\n\nfunc processNetworkPacket(dataID int) {\n\tpkt := packetPool.Get().(*LargePacket)\n\tdefer packetPool.Put(pkt) // Возврат в пул после обработки\n\n\tpkt.Length = 1024\n\tpkt.Payload[0] = byte(dataID % 255)\n}\n\nfunc main() {\n\tvar wg sync.WaitGroup\n\tconst totalPackets = 50\n\n\twg.Add(totalPackets)\n\tfor i := 0; i < totalPackets; i++ {\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\t\t\tprocessNetworkPacket(id)\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Printf("Успешно обработано %d тяжелых пакетов без нагрузки на GC через sync.Pool!\\n", totalPackets)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Успешно обработано 50 тяжелых пакетов без нагрузки на GC через sync.Pool!'}], 'under_the_hood': '`sync.Pool` выделяет память на арене `mheap` один раз и циклически распределяет её по локальным кешам `poolLocal`.', 'pitfalls': 'Всегда обнуляйте поля структуры перед использованием, так как объект из пула содержит остаточные данные от предыдущего владельца.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему sync.Pool не подходит для пулов сетевых соединений (Connection Pool)?»\n**Ответ:** Потому что `sync.Pool` не гарантирует сохранение объектов: во время сборки мусора (GC) неиспользуемые объекты из пула могут быть удалены в любой момент. Для соединений к БД используют специализированные пулы (`database/sql`).'}, {'num': 81, 'title': 'Анализ забытого pool.Put: потеря оптимизации без утечки памяти и мониторинг ReadMemStats', 'task': 'Напиши программу с `sync.Pool`, где забываешь `Put` — покажи, что это не утечка памяти (GC соберёт), но теряется преимущество пула. Замерь аллокации через `runtime.ReadMemStats`.', 'theory': 'Если объект забран из `sync.Pool.Get()`, но не возвращен через `Put()`, он превращается в обычный объект кучи. Сборщик мусора корректно удалит его при следующем цикле GC. Утечки памяти не произойдет, но программа потеряет выигрыш от пулинга, постоянно выполняя новые аллокации `mallocgc`.', 'step_by_step': '1. Замерим аллокации через `runtime.ReadMemStats` до запуска.\n2. Вызовем 100 раз `pool.Get()` без `pool.Put()`.\n3. Замерим `TotalAlloc` и количество созданных объектов `Mallocs`.\n4. Сравним со сценарием с возвратом в пул.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"runtime"\n\t"sync"\n)\n\nvar testPool = sync.Pool{\n\tNew: func() any {\n\t\treturn make([]byte, 1024*1024) // 1 МБ\n\t},\n}\n\nfunc main() {\n\tvar m1, m2 runtime.MemStats\n\n\t// 1. Сценарий: забыли Put\n\truntime.GC()\n\truntime.ReadMemStats(&m1)\n\n\tfor i := 0; i < 5; i++ {\n\t\tbuf := testPool.Get().([]byte)\n\t\t_ = buf[0]\n\t\t// Забыли вызвать testPool.Put(buf)\n\t}\n\n\truntime.ReadMemStats(&m2)\n\tallocWithoutPut := m2.TotalAlloc - m1.TotalAlloc\n\tfmt.Printf("Аллокаций памяти БЕЗ Put: %d КБ (создано 5 новых объектов)\\n", allocWithoutPut/1024)\n\n\t// 2. Сценарий: правильный Put\n\truntime.GC()\n\truntime.ReadMemStats(&m1)\n\n\tfor i := 0; i < 5; i++ {\n\t\tbuf := testPool.Get().([]byte)\n\t\t_ = buf[0]\n\t\ttestPool.Put(buf) // Возврат в пул\n\t}\n\n\truntime.ReadMemStats(&m2)\n\tallocWithPut := m2.TotalAlloc - m1.TotalAlloc\n\tfmt.Printf("Аллокаций памяти С Put:   %d КБ (объект переиспользован)\\n", allocWithPut/1024)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# Аллокаций памяти БЕЗ Put: 5120 КБ (создано 5 новых объектов)\n# Аллокаций памяти С Put:   1024 КБ (объект переиспользован)'}], 'under_the_hood': '`m.TotalAlloc` считает совокупный объем выделенной памяти за все время работы программы.', 'pitfalls': 'Не забывайте `defer pool.Put()`, иначе выигрыш от пула сойдет на нет.', 'bigtech_interview': '**Вопрос с собеседования:** «Приводит ли забытый pool.Put() к Goroutine Leak или Memory Leak?»\n**Ответ:** Нет! Невозвращенный объект просто теряет ссылку после выхода из функции и собирается штатным сборщиком мусора GC без утечки памяти.'}, {'num': 82, 'title': 'Реализация барьера синхронизации (Barrier) на базе sync.Cond', 'task': 'Используй `sync.Cond` (условная переменная): создай `sync.Cond` с `sync.Mutex`. Одна горутина ждёт `cond.Wait()`, пока другая не вызовет `cond.Signal()` или `cond.Broadcast()`. Реализуй "очередь ожидания" или "barrier".', 'theory': 'Барьер синхронизации (Barrier) — примитив многопоточности, удерживающий группу из N горутин до тех пор, пока абсолютно все участники группы не достигнут контрольной точки.', 'step_by_step': '1. Создадим структуру `Barrier struct { mu sync.Mutex; cond *sync.Cond; count int; total int }`.\n2. Реализуем метод `Wait()`, который увеличивает `count` и засыпает на `cond.Wait()`, если `count < total`.\n3. Когда `count == total`, последний участник вызывает `cond.Broadcast()`.\n4. Запустим 3 воркера и проверим одновременный старт.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"sync"\n\t"time"\n)\n\ntype Barrier struct {\n\tmu      sync.Mutex\n\tcond    *sync.Cond\n\tcount   int\n\ttotal   int\n\tbarrier bool\n}\n\nfunc NewBarrier(total int) *Barrier {\n\tb := &Barrier{total: total}\n\tb.cond = sync.NewCond(&b.mu)\n\treturn b\n}\n\nfunc (b *Barrier) Await(workerID int) {\n\tb.mu.Lock()\n\tdefer b.mu.Unlock()\n\n\tb.count++\n\tif b.count == b.total {\n\t\tfmt.Printf("[Worker #%d] Последний участник достиг барьера! Пробуждение всех...\\n\\n", workerID)\n\t\tb.barrier = true\n\t\tb.cond.Broadcast() // Пробуждаем всех\n\t} else {\n\t\tfmt.Printf("[Worker #%d] Достиг барьера (%d/%d), ожидаю остальных...\\n", workerID, b.count, b.total)\n\t\tfor !b.barrier {\n\t\t\tb.cond.Wait()\n\t\t}\n\t}\n}\n\nfunc main() {\n\tconst totalParticipants = 3\n\tbarrier := NewBarrier(totalParticipants)\n\tvar wg sync.WaitGroup\n\n\tfor i := 1; i <= totalParticipants; i++ {\n\t\twg.Add(1)\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\t\t\ttime.Sleep(time.Duration(id*10) * time.Millisecond)\n\t\t\tbarrier.Await(id)\n\t\t\tfmt.Printf(" -> [Worker #%d] Продолжил параллельное выполнение после барьера!\\n", id)\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Println("\\nВсе воркеры успешно преодолели барьер!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Worker #1] Достиг барьера (1/3), ожидаю остальных...\n# [Worker #2] Достиг барьера (2/3), ожидаю остальных...\n# [Worker #3] Последний участник достиг барьера! Пробуждение всех...\n# \n#  -> [Worker #3] Продолжил параллельное выполнение после барьера!\n#  -> [Worker #1] Продолжил параллельное выполнение после барьера!\n#  -> [Worker #2] Продолжил параллельное выполнение после барьера!\n# \n# Все воркеры успешно преодолели барьер!'}], 'under_the_hood': '`b.cond.Broadcast()` переводит все ожидающие горутины из `notifyList` в очередь выполнения планировщика.', 'pitfalls': 'Для многократного прохождения барьера несколькими фазами требуется сбрасывать `count = 0` и `barrier = false` (CyclicBarrier).', 'bigtech_interview': '**Вопрос с собеседования:** «В каких распределенных алгоритмах применяется паттерн Barrier?»\n**Ответ:** В распределенных вычислениях (Bulk Synchronous Parallel, BSP), пакетных ML-тренировках (синхронизация градиентов между GPU-нодами) и матричных вычислениях.'}]
